/* ---------- forms of the same drug (magnesium oxide / citrate / glycinate, testosterone gel / cypionate, fluticasone nasal ...) ---------- */
var FORM_RE = /\b(topical|ophthalmic|nasal|inhaled|inhalation|oral|iv|injection|injectable|intravenous|transdermal|patch|extended[- ]release|er|xr|sr|long[- ]acting|cream|gel|ointment|lotion|foam|solution|suspension|vaginal|intravesical|intravitreal|implant|sinus|eye|drops|dental|paste|granules|low|dose|rosacea|lar|subcutaneous|liposomal|liposome|auto[- ]injector|ring|spray|exhalation|sublingual|chewable|odt|tablets?|capsules?|film|cloth|with|sorbitol|deoxycholate)\b/g;
