  if (f.getAttribute("data-rvform")) { e.preventDefault(); store("reviewer", { by: "", cred: ($("#rvcred") || {}).value.trim(), lic: ($("#rvlic") || {}).value.trim(), licno: ($("#rvlicno") || {}).value.trim(), licst: ($("#rvlicst") || {}).value.trim(), agree: !!($("#rvagree") || {}).checked, role: ($("#rvrole") || {}).value || "" }); Admin.msg = "Reviewer saved."; return render(); }
