function adminClick(t) {
  var a = A(), d = t.dataset;
  if (d.atab) { a.tab = d.atab; a.form = a.qedit = a.sedit = null; a.hist = null; Admin.msg = ""; if (d.atab === "history") a.log = null; return render(); }
  if (d.rqopen) { a.rqid = d.rqopen; render(); return window.scrollTo(0, 0); }
  if (d.psedit) { var ps = PS.sets.filter(function (x) { return x.id === d.psedit; })[0]; a.psedit = JSON.parse(JSON.stringify(ps)); Admin.msg = ""; render(); return window.scrollTo(0, 0); }
  if (d.aedit) { a.tab = "drugs"; a.form = recordOf(d.aedit); a.hist = null; Admin.msg = ""; render(); return window.scrollTo(0, 0); }
  if (d.aqedit) { var q = DB.Q.filter(function (x) { return qid(x) === d.aqedit; })[0]; if (!q) { Admin.msg = "That question is no longer in the bank."; return render(); } a.tab = "questions"; a.qedit = JSON.parse(JSON.stringify(q)); Admin.msg = ""; render(); return window.scrollTo(0, 0); }
  if (d.asedit) { var s = DB.SCEN.filter(function (x) { return x.id === d.asedit; })[0]; a.sedit = JSON.parse(JSON.stringify(s)); Admin.msg = ""; render(); return window.scrollTo(0, 0); }
  if (d.arestore) { var h = (a.hist || []).filter(function (x) { return String(x.rev) === d.arestore; })[0]; if (h && h.record) { var cur = a.form; a.form = JSON.parse(JSON.stringify(h.record)); a.form.rev = cur.rev; Admin.msg = "Version " + h.rev + " loaded into the form. Save to make it live."; render(); } return; }
  switch (d.aact) {
    case "newdrug": a.form = blankRecord(); a.hist = null; Admin.msg = ""; render(); return window.scrollTo(0, 0);
    case "back": a.form = null; a.hist = null; return render();
    case "savedrug": return saveDrug();
    case "hist": loadHist(a.form.id, function (l) { a.hist = l; render(); }); return;
    case "newq": a.qedit = { isNew: true, lv: a.qf.lv || "paramedic", d: "", q: "", a: "", w: ["", "", ""], x: "", cat: "" }; Admin.msg = ""; return render();
    case "qback": a.qedit = null; return render();
    case "saveq": return saveQ();
    case "news": a.sedit = { isNew: true, id: "x" + Date.now().toString(36), side: "ph", cat: "", title: "", text: "", vitals: [], correct: [], ok: [], wrong: [], why: "", notes: {} }; Admin.msg = ""; return render();
    case "sback": a.sedit = null; return render();
    case "saves": return saveS();
    case "rpf": RP.filter = d.rpf; return render();
    case "rpreload": RP.list = null; return render();
    case "rpresolve": return setReportStatus(d.rpid, "resolved");
    case "rpreopen": return setReportStatus(d.rpid, "open");
    case "modremove": return modSet(d.muid, true);
    case "modunblock": return modSet(d.muid, false);
    case "rqnext": a.rqskip = []; rqAdvance(); render(); return window.scrollTo(0, 0);
    case "rqback": a.rqid = null; return render();
    case "rqskip": a.rqskip = (a.rqskip || []).concat([a.rqid]); rqAdvance(); render(); return window.scrollTo(0, 0);
    case "rqapprove": return approveReview();
    case "rqfix": a.tab = "drugs"; a.form = recordOf(a.rqid); a.hist = null; Admin.msg = "Make the changes, set Medical review to reviewed if appropriate, and save."; render(); return window.scrollTo(0, 0);
    case "newps": a.psedit = { isNew: true, agency: "", name: "", state: "TX", type: "EMS", levels: [], status: "unpublished", drugs: {} }; Admin.msg = ""; return render();
    case "psback": a.psedit = null; return render();
    case "saveps": return savePs();
    case "psaddrow": a.psedit = readPsForm(); a.psedit.isNew = A().psedit.isNew; return render();
  }
}

/* ---------- Terrarium (shop): earn Sticks, buy and equip bugs, outfits, faces, colors ---------- */
// Sticks per correct answer, by the level of the question. Higher scope pays more.
var STICKV = { emt: 1, cna: 1, aemt: 1, lvn: 1, gen: 1, paramedic: 1, rn: 1, ms1: 1, flight: 1, ms3: 1, intern: 1 };
var PERFECT_BONUS = 10, ACH_BONUS = 25;
function perfectBonus(st, total, correct) { if (st.perfectPaid || total < 10 || correct !== total) return false; st.perfectPaid = true; earn(PERFECT_BONUS); saveProg(); return true; }
var START_STICKS = 20;
function sticks() { var P = Prog.d; return START_STICKS + (P.earned || 0) - (P.spent || 0); }
