  if (ac.length + ap.length >= 2) add("high", "Bleeding risk: more than one anticoagulant or antiplatelet", ac.concat(ap), "Combined blood thinners raise the risk of serious bleeding. Bruising, black stools and falls are common questions to ask about.");
  if (ns.length && ac.length + ap.length) add("high", "NSAID plus a blood thinner", ns.concat(ac, ap), "NSAIDs add GI bleeding risk to anticoagulants and antiplatelets.");
  var ssr = hasAny(ids, "sero").filter(function (x) { return /SSRI|SNRI/i.test(get(DB.drugs[x], 0, 4) + " " + get(DB.drugs[x], 0, 3)); });
  if (ssr.length && ac.length + ap.length) add("med", "SSRI or SNRI plus a blood thinner", ssr.concat(ac, ap), "Studies show SSRIs and SNRIs impair platelet serotonin uptake and raise bleeding risk with anticoagulants and antiplatelets; their FDA labels warn about this combination.");
