  if (op.length && bz.length) add("high", "Opioid plus benzodiazepine", op.concat(bz), "FDA boxed warning: profound sedation, respiratory depression, coma and death. Breathing is typically monitored closely, and naloxone reverses the opioid part.", "syn");
  else if (op.length && cn.length) add("med", "Opioid plus another sedating drug", op.concat(cn), "Additive CNS and respiratory depression.");
  var mao = hasAny(ids, "maoi"), se = hasAny(ids, "sero").filter(function (x) { return mao.indexOf(x) < 0; });
