  if (ids.indexOf("lithium") >= 0) { var li = ns.concat(hasAny(ids, "acei"), hasAny(ids, "arb"), hasAny(ids, "thiazide")); if (li.length) add("high", "Lithium level may rise", ["lithium"].concat(li), "NSAIDs, ACE inhibitors, ARBs and thiazides reduce lithium clearance. Toxicity signs include tremor, confusion and vomiting.", "neg"); }
  if (ids.indexOf("warfarin") >= 0) { var wi = hasAny(ids, "warfint"); if (wi.length) add("high", "Warfarin interaction", ["warfarin"].concat(wi), "These drugs change warfarin's effect. The INR is typically checked more often.", "neg"); }
  var stt = hasAny(ids, "statin3a4"), inh = hasAny(ids, "inhib3a4"); if (stt.length && inh.length) add("med", "Statin plus a CYP3A4 inhibitor", stt.concat(inh), "Higher statin levels raise myopathy and rhabdomyolysis risk.", "neg");
