  if (ids.indexOf("clopidogrel") >= 0 && ids.indexOf("omeprazole") >= 0) add("low", "Clopidogrel plus omeprazole", ["clopidogrel", "omeprazole"], "Omeprazole may reduce clopidogrel activation (CYP2C19).", "neg");
  var fq = hasAny(ids, "fq"), stx = hasAny(ids, "steroid"); if (fq.length && stx.length) add("med", "Fluoroquinolone plus corticosteroid", fq.concat(stx), "Higher risk of tendon rupture.");
  /* one drug works against the other */
  var nsb = hasAny(ids, "nsbb"), b2 = hasAny(ids, "b2ag"); if (nsb.length && b2.length) add("med", "Nonselective beta blocker plus a beta-2 agonist", nsb.concat(b2), "Nonselective beta blockers also block beta-2 receptors in the airways. They can blunt the bronchodilating effect of albuterol-type drugs and can trigger bronchospasm in asthma or COPD.", "neg");
