    var weak = {}; st.forEach(function (s) { var r = ((s.cls || {})[cid] || {}).res || {}; Object.keys(r).forEach(function (x) { (r[x].weak || []).forEach(function (id) { weak[id] = (weak[id] || 0) + 1; }); }); });
