  CL.busy = true; render();
  CL.db.doc("classcodes/" + code).get().then(function (s) { if (s.exists) code = newCode(); return CL.db.doc("classcodes/" + code).set({ inst: CL.uid, cls: id, ts: Date.now() }); })
    .then(function () { CL.mine.list = (CL.mine.list || []).concat([{ id: id, name: name.slice(0, 80), code: code, level: lv, created: Date.now(), asg: [] }]); return saveMine(); })
