  if (!t) { S.clMsg = "Give the assignment a title."; return render(); }
  var a = { id: "a" + Date.now().toString(36), title: t.slice(0, 80), level: $("#alevel").value, n: +$("#an").value, due: $("#adue").value || "" };
  if (src === "all") a.src = "all"; else if (src[0] === "g") { a.src = "group"; a.srcv = DB.GROUPS[+src.slice(1)].name; } else { a.src = "cat"; a.srcv = src.slice(1); }
