  var R = CL.roster, e = R.cls[opt.cls] || (R.cls[opt.cls] = { joined: Date.now(), res: {} });
  e.res[opt.asg.id] = { pct: sc.pct, n: sc.n, c: sc.c, ts: Date.now(), weak: weak.slice(0, 8) };
