/* weekly leaderboard (opt-in) */
function lbRoll() { var P = Prog.d, wk = weekKey(); if (P.week !== wk) { P.week = wk; P.weekBase = P.xp || 0; } }
function myWeekXp() { lbRoll(); return (Prog.d.xp || 0) - (Prog.d.weekBase || 0); }
function lbPush() {
  if (!SOCIAL) return;
  var P = Prog.d; if (!P.lbName || !Prog.db || !Prog.uid || isMinor() || LG.blocked.indexOf(lbPid()) >= 0) return;
  lbRoll(); var av = { b: myBug().id, f: myFace(), w: myWear(), s: P.style || "classic" }, sig = JSON.stringify(av);
  if (Date.now() - (CL.lbTs || 0) < 20000 && sig === CL.lbSig) return; CL.lbTs = Date.now(); CL.lbSig = sig;
  var pid = lbPid(), row = { name: P.lbName, week: P.week, weekXp: Math.max(0, Math.round(P.xp - P.weekBase)), total: Math.round(P.xp || 0), ts: Date.now(), av: av };
  (P.lbOwned === pid ? Promise.resolve() : Prog.db.doc("lbowner/" + pid).set({ uid: Prog.uid }).then(function () { P.lbOwned = pid; saveProg(); }))
    .then(function () { return Prog.db.doc("leaderboard/" + pid).set(row); }).catch(function () {});
}
/* random public leaderboard ID kept in the private progress record */
function lbPid() { var P = Prog.d; if (!P.lbPid) { var a = "abcdefghijkmnpqrstuvwxyz23456789", s = ""; var r = (window.crypto && crypto.getRandomValues) ? crypto.getRandomValues(new Uint8Array(20)) : null; for (var i = 0; i < 20; i++) s += a[(r ? r[i] : Math.floor(Math.random() * 256)) % a.length]; P.lbPid = s; } return P.lbPid; }
function lbAvatar(av) {
  av = av && typeof av === "object" ? av : {};
  var b = BUGS.filter(function (x) { return x.id === av.b; })[0] || bugById("starter");
  var face = FACES.some(function (f) { return f[0] === av.f; }) ? av.f : "happy", wear = {};
  if (av.w && typeof av.w === "object") Object.keys(av.w).forEach(function (slot) { var it = ITEMS_BY[av.w[slot]]; if (it && it.slot === slot) wear[slot] = it.id; });
  var st = STYLES.filter(function (x) { return x[0] === av.s; })[0], a = bugArt(b, "lbbug", { mood: face, wear: wear });
  return st && st[3] ? a.replace('<svg class="bug', '<svg style="filter:' + st[3] + '" class="bug') : a;
}
function lbView() {
  if (!SOCIAL) return "";
  if (!HASDB) return "";
  var P = Prog.d, c = '<h3 class="eh small">This week\'s leaderboard</h3>';
  if (isMinor()) return c + '<p class="muted small">The public leaderboard is for users 18 and older.</p>';
  if (P.lbName && Prog.uid && LG.blocked.indexOf(lbPid()) >= 0) return c + '<p class="muted small">Your display name was removed by a moderator. Contact ' + esc(CONTACT) + ' with questions.</p>';
  if (S.lbMsg) c += '<p class="presult" role="alert">' + esc(S.lbMsg) + '</p>';
  if (!P.lbName) return c + '<form class="calcform" data-lbjoin="1"><input class="pinput" id="lbname" placeholder="Display name (shown to other DrugBug users)" maxlength="40" style="max-width:300px"><button class="btn" type="submit">Join the leaderboard</button></form><p class="muted small">Optional. Only your display name and XP are shown. Use a first name or nickname, keep it respectful, and leave any time.</p>';
  if (!CL.lb) { CL.lb = "loading"; if (Prog.db) Prog.db.collection("leaderboard").where("week", "==", weekKey()).limit(200).get().then(function (qs) { CL.lb = qs.docs.filter(function (d) { return LG.blocked.indexOf(d.id) < 0; }).map(function (d) { return d.data(); }).filter(function (r) { return nameOk(r.name); }).sort(function (a, b) { return b.weekXp - a.weekXp; }).slice(0, 20); render(); }).catch(function () { CL.lb = []; render(); }); else CL.lb = []; }
  if (CL.lb === "loading") return c + '<p class="muted">Loading…</p>';
  var L = CL.lb.length ? CL.lb : [{ name: P.lbName, weekXp: myWeekXp() }];
  return c + '<ol class="lb">' + L.map(function (r, i) { return '<li class="' + (r.name === P.lbName ? "me" : "") + '"><span class="rk">' + (i + 1) + '</span><span class="lbav">' + (r.name === P.lbName ? myBugArt("lbbug") : lbAvatar(r.av)) + '</span><span class="nm">' + esc(r.name) + '</span><span class="xp">' + (r.weekXp || 0).toLocaleString() + ' XP</span></li>'; }).join("") + '</ol><p class="muted small">Weekly XP resets every Monday. Showing as <strong>' + esc(P.lbName) + '</strong> · <button class="linkish" data-act="lbleave">Leave the leaderboard</button></p>';
}

/* ---------- Clinical review queue + protocol sets (Control Center) and protocol-aware content ---------- */
function reviewer() { return store("reviewer") || { by: "", cred: "" }; }
function rvReady(rv) { return !!(rv.agree && rv.lic && rv.licno && rv.role); }
/* reviewer roles: who may approve what, and at which level */
var RVROLES = [["paramedic", "Paramedic / Flight paramedic", "ems"], ["rn", "Registered nurse (RN)", "rn"], ["app", "Nurse practitioner / Physician assistant", "all"], ["pharmd", "Pharmacist (PharmD/RPh)", "all", 1], ["md", "Physician (MD/DO)", "all", 1]];
function rvRole(rv) { return RVROLES.filter(function (x) { return x[0] === (rv && rv.role); })[0] || null; }
function rvVerifier(rv) { var r = rvRole(rv); return !!(r && r[3]); }
function rvScopeName(rv) { var r = rvRole(rv); return !r ? "" : r[2] === "ems" ? "prehospital and flight drugs" : r[2] === "rn" ? "nursing drugs (not the med-school-only drugs)" : "all drugs"; }
function canReview(rv, id) { var r = rvRole(rv); if (!r) return false; if (r[2] === "ems") return DB.PHIDS.indexOf(id) >= 0; if (r[2] === "rn") return (DB.MEDIDS || []).indexOf(id) < 0; return true; }
function rvLevel(d) { var r = (d && d.review) || {}; if (r.status !== "reviewed") return "none"; return r.level === "verified" || r.ver ? "verified" : "clinical"; }
