var BADW = ["fuck", "shit", "bitch", "cunt", "dick", "cock", "pussy", "asshole", "bastard", "slut", "whore", "fag", "nigg", "retard", "rape", "nazi", "hitler", "porn", "sex", "penis", "vagina", "tits", "boob", "cum", "jizz", "kkk", "spic", "chink", "kike", "wetback", "tranny", "dyke", "twat", "wank", "prick", "piss", "damn", "hell"];
function nameOk(s) {
  var n = String(s || "").toLowerCase().replace(/[@4]/g, "a").replace(/3/g, "e").replace(/[1!|]/g, "i").replace(/0/g, "o").replace(/[5$]/g, "s").replace(/7/g, "t").replace(/[^a-z]/g, "");
  if (/(.)\1{4,}/.test(n)) return false;
  return !BADW.some(function (w) { return w === "hell" || w === "cum" || w === "sex" || w === "dick" || w === "piss" ? new RegExp("(^|[^a-z])" + w + "([^a-z]|$)").test(String(s).toLowerCase()) : n.indexOf(w) >= 0; });
}
