/* delete my data */
/* deletes every cloud record DrugBug keeps for this account; cb(allOk, hadDb) */
function deleteCloudData(cb) {
  var db = Prog.db || CL.db, uid = Prog.uid || CL.uid, jobs = [];
  if (db && uid) {
    ["data/users/" + uid + "/progress", "data/users/" + uid + "/nrhistory", "data/users/" + uid + "/profile", "rosters/" + uid, "reports/" + uid, "protocolRequests/" + uid].concat(Prog.d.lbPid ? ["leaderboard/" + Prog.d.lbPid, "lbowner/" + Prog.d.lbPid] : []).forEach(function (p) { jobs.push(db.doc(p).delete()); });
    jobs.push(db.collection("protoFiles/" + uid + "/photos").limit(200).get().then(function (qs) { return Promise.all(qs.docs.map(function (d) { return db.doc("protoFiles/" + uid + "/photos/" + d.id).delete(); })); }));
    jobs.push(db.doc("classes/" + uid).get().then(function (s) {
      var list = (s.exists && s.data().list) || [];
      return Promise.all(list.map(function (k) { return db.doc("classcodes/" + k.code).delete().catch(function () {}); })).then(function () { return db.doc("classes/" + uid).delete(); });
    }));
  }
  Promise.all(jobs.map(function (p) { return p.then(function () { return true; }, function () { return false; }); })).then(function (r) { cb(r.every(Boolean), !!(db && uid)); });
}
function deleteMyData() {
  S.delState = "busy"; render();
  deleteCloudData(function (ok, had) {
    try { Object.keys(localStorage).forEach(function (k) { if (k.indexOf("drugbug:") === 0) localStorage.removeItem(k); }); } catch (e) {} if (typeof akWipeAll === "function") { akWipeAll().catch(function () {}); ANK.decks = null; ANK.st = null; }
    Prog.d = blankProg(); Scores.items = []; CL.loaded = false; CL.lb = null; CL.roster = null; CL.mine = null;
    S.delState = ok && had ? "done" : "partial"; render();
  });
}

/* leave a class (deletes this learner's results for it) */
function leaveClass(cid) {
  var R = CL.roster; if (!R) return;
  R.classIds = (R.classIds || []).filter(function (x) { return x !== cid; }); delete (R.cls || {})[cid]; delete CL.dash["L" + cid];
  var p = R.classIds.length ? saveRoster() : CL.db.doc("rosters/" + CL.uid).delete();
  p.then(function () { S.clMsg = "You left the class. Your results for it were deleted."; }).catch(function () { S.clMsg = "Could not leave the class right now."; }).then(render);
}
function ferpaNote() { return '<p class="muted small ferpa"><strong>Privacy for classes:</strong> instructors see the name you enter and your assignment scores. Use a first name or nickname. Leaving a class deletes your results for it. Schools that need a FERPA data agreement should contact ' + esc(CONTACT) + ' before using Classes for grades. Never put patient information in class names or assignments.</p>'; }

/* leaderboard moderation (owner) */
function loadBlocked(db) { return db.doc("leaderboard/~blocked").get().then(function (s) { LG.blocked = (s.exists && s.data().ids) || []; }).catch(function () {}); }
function initLegal() {
  if (!window.claude || typeof window.claude.use !== "function") return;
  Promise.all([window.claude.use("user"), window.claude.use("db")]).then(function (r) {
    var u = r[0], db = r[1]; if (u) u.isOwner().then(function (o) { LG.owner = !!o; }).catch(function () {});
    if (db) loadBlocked(db);
  }).catch(function () {});
  setTimeout(syncAgree, 2500);
}
function modView() {
  if (!LG.owner) return '<p class="muted">Only the owner can moderate the leaderboard.</p>';
  if (!LG.mod) { LG.mod = "loading"; Dex.db.collection("leaderboard").limit(500).get().then(function (qs) { LG.mod = qs.docs.filter(function (d) { return d.id !== "~blocked"; }).map(function (d) { var x = d.data(); x.uid = d.id; return x; }).sort(function (a, b) { return (b.ts || 0) - (a.ts || 0); }); render(); }).catch(function () { LG.mod = []; render(); }); }
  if (LG.mod === "loading") return '<p class="muted">Loading leaderboard…</p>';
  var c = '<p class="muted small">Remove a display name to take it off the leaderboard and stop it from coming back. Names that fail the word filter are flagged.</p>';
  if (!LG.mod.length) return c + '<p class="muted">No one is on the leaderboard yet.</p>';
  return c + '<div class="alist">' + LG.mod.map(function (r) { var bl = LG.blocked.indexOf(r.uid) >= 0; return '<div class="arow"><strong>' + esc(r.name || "(no name)") + '</strong><span class="muted small">' + esc(r.week || "") + ' · ' + (r.weekXp || 0) + ' XP</span>' + (nameOk(r.name) ? '' : pill("Flagged", "warn")) + (bl ? pill("Removed", "off") + '<button class="btn small ghost" data-aact="modunblock" data-muid="' + esc(r.uid) + '">Allow again</button>' : '<button class="btn small again" data-aact="modremove" data-muid="' + esc(r.uid) + '">Remove</button>') + '</div>'; }).join("") + '</div>';
}
function modSet(uid, block) {
  var ids = LG.blocked.filter(function (x) { return x !== uid; }); if (block) ids.push(uid);
  Admin.busy = true;
  Dex.db.doc("leaderboard/~blocked").set({ ids: ids, ts: Date.now() }).then(function () { LG.blocked = ids; return block ? Dex.db.doc("leaderboard/" + uid).delete() : null; })
    .then(function () { Admin.msg = block ? "Display name removed from the leaderboard." : "User can join the leaderboard again."; LG.mod = null; CL.lb = null; })
    .catch(function (e) { Admin.msg = "Could not update (" + (e && e.code || "error") + ")."; }).then(function () { Admin.busy = false; render(); });
}

/* compliance checklist (Control Center) */
var COMPLY = [
  ["lawyer", "Terms of Use and Privacy Policy reviewed by a lawyer", "Draft text is in the app footer. Governing law set to Texas (Brazos County); confirm with a lawyer."],
  ["tm", "Trademark and non-affiliation wording reviewed by a lawyer", "Exam names are used descriptively with a non-affiliation line."],
  ["eo", "Errors-and-omissions (professional liability) insurance in place", "Ask a broker about E&O for educational health content, plus general liability and cyber."],
  ["reviewers", "Signed agreement on file for every clinical reviewer", "Scope, credentials, payment, content responsibility, confidentiality. Approvals require the reviewer agreement box."],
  ["ismp", "ISMP permission terms confirmed before commercial use", "Attribution is shown in Safety drills and Disclaimers."],
  ["protocols", "Written permission and medical director sign-off on file for every agency protocol set", "Protocol sets cannot be published without the permission box."],
  ["fda", "FDA: marketing stays educational; regulatory advice before promoting any tool for patient care", "Tools are labeled educational use only. Dose Cards and Pediatric dosing practice were removed."],
  ["ferpa", "FERPA: data agreement template ready for schools using Classes", "Consider a separate DrugBug copy per school for graded work."],
  ["coppa", "Age gate confirmed (18+ only)", "Users under 18 are blocked at the agreement screen. App Store age rating set to 18+."],
  ["a11y", "Accessibility review (WCAG 2.1 AA / VPAT) before selling to schools", ""],
  ["entity", "Business entity, registered agent and app-store/payment terms in order", ""]
];
var CP = { doc: null };
function complianceView() {
  if (!Dex.db) return '<p class="muted">Connect to the database to track compliance.</p>';
  if (!CP.doc) { CP.doc = "loading"; Dex.db.doc("compliance/checklist").get().then(function (s) { CP.doc = (s.exists && s.data()) || { items: {} }; render(); }).catch(function () { CP.doc = { items: {} }; render(); }); }
  if (CP.doc === "loading") return '<p class="muted">Loading…</p>';
  var it = CP.doc.items || {}, done = COMPLY.filter(function (x) { return it[x[0]] && it[x[0]].done; }).length;
  var c = '<p class="muted small">Business and legal to-dos for running DrugBug. Not legal advice: have a lawyer confirm each item. ' + done + ' of ' + COMPLY.length + ' done.</p><div class="alist">';
  c += COMPLY.map(function (x) { var r = it[x[0]] || {}; return '<div class="arow cprow"><label class="chk"><input type="checkbox" data-cpk="' + x[0] + '"' + (r.done ? " checked" : "") + '> <strong>' + esc(x[1]) + '</strong></label>' + (x[2] ? '<span class="muted small">' + esc(x[2]) + '</span>' : '') + (r.done && r.ts ? '<span class="muted small">Checked ' + esc(fmtDate(r.ts)) + '</span>' : '') + '</div>'; }).join("");
  return c + '</div>';
}
function toggleComply(k, on) {
  if (!CP.doc || CP.doc === "loading") return;
  var d = JSON.parse(JSON.stringify(CP.doc)); d.items = d.items || {}; d.items[k] = { done: on, ts: Date.now(), by: Admin.uid || "" };
  Dex.db.doc("compliance/checklist").set(d).then(function () { CP.doc = d; Admin.msg = "Checklist saved."; }).catch(function (e) { Admin.msg = "Could not save (" + (e && e.code || "error") + ")."; }).then(render);
}

/* click / change hooks */
function legalClick(t, a) {
  if (a.legal) { openLegal(a.legal); return true; }
  if (a.gage) return false;
  switch (a.act) {
    case "gateok": acceptGate(); return true;
    case "discok": acceptDisc(); return true;
    case "legalback": legalBack(); return true;
    case "delask": S.delState = "ask"; render(); return true;
    case "delno": S.delState = null; render(); return true;
    case "delyes": deleteMyData(); return true;
  }
  if (a.clleave) { leaveClass(a.clleave); return true; }
  return false;
}
document.addEventListener("change", function (e) {
  var t = e.target;
  if (t.getAttribute && t.getAttribute("data-gage")) { S.gate = S.gate || {}; S.gate.age = t.getAttribute("data-gage"); render(); }
  else if (t.id === "gok") { S.gate = S.gate || {}; S.gate.ok = t.checked; var b = $('[data-act="gateok"]'); if (b) b.disabled = !(S.gate.age && S.gate.ok); }
  else if (t.getAttribute && t.getAttribute("data-cpk")) toggleComply(t.getAttribute("data-cpk"), t.checked);
});

/* first run: choose your path, get your starter beetle */
function grubFix() { /* give each path its own starter beetle once (older builds used the plain beetle) */
  var P = Prog.d; if (!P) return;
  /* mantis and stick bug used to be free for everyone; testers already using one keep it */
  if ((P.avatar === "free-mantis" || P.avatar === "free-stickbug") && (P.owned || []).indexOf(P.avatar) < 0) { P.owned = (P.owned || []).concat([P.avatar]); saveProg(); }
  if (!P.role || P.grubFix) return;
  var R = ROLES.filter(function (x) { return x[0] === P.role; })[0] || ROLES[0], g = R[3];
  if ((P.owned || []).indexOf(g) < 0) P.owned = (P.owned || []).concat([g]);
  if (!P.avatar || P.avatar === "starter") { P.avatar = g; P.avatarTs = Date.now(); }
  P.grubFix = 1; saveProg();
}
var ROLES = [["ev", "Everyday Health", "Not a clinician: medicines, vitamins and your body", "grub-everyday", "everyday"], ["ph", "Prehospital", "EMT, AEMT, Paramedic or Flight Paramedic", "grub-medic", "levels"], ["rn", "Nursing", "CNA, LVN/LPN or RN", "grub-nurse", "nlevels"], ["md", "Medical School", "MS1-MS2, MS3-MS4 or Intern", "grub-doc", "mlevels"], ["im", "Imaging", "X-ray, CT, MRI, nuclear medicine or IR", "grub-imaging", "ilevels"]];
function needRole() { return !!agreeRec() && !Prog.d.role && S.view !== "legal"; }
function roleView() {
  return '<div class="gate rolepick"><h1>What are you studying for?</h1><p>Pick your path. You will get a starter beetle dressed for that path, and you can explore every route anytime.</p><button class="rolecard role-gen bugdexrole" data-role="none">' + bugSVG("sage") + '<span class="rtx"><strong>BugDex</strong><span>Every medication in DrugBug, A to Z, explained by Professor Sage. Great for anyone, or if you are not sure yet.</span><span class="rgrub">Starter: ' + esc(bugById(ROLES[0][3]).name) + ' · browse everything</span></span></button><div class="roles">' +
    ROLES.map(function (r) { return '<button class="rolecard role-' + r[0] + '" data-role="' + r[0] + '">' + bugArt(bugById(r[3]), "rolebug", { mood: "happy" }) + '<span class="rtx"><strong>' + r[1] + '</strong><span>' + r[2] + '</span><span class="rgrub">Starter: ' + esc(bugById(r[3]).name) + '</span></span></button>'; }).join("") +
    '</div></div>';
}
function pickRole(r) {
  var R = ROLES.filter(function (x) { return x[0] === r; })[0];
  Prog.d.role = r;
  var G = R || ROLES[0]; /* every path starts with its version of the starter beetle; BugDex browsers get the Garden Beetle */
  { var g = G[3]; if ((Prog.d.owned || []).indexOf(g) < 0) Prog.d.owned = (Prog.d.owned || []).concat([g]); if (!Prog.d.avatar || Prog.d.avatar === "starter") { Prog.d.avatar = g; Prog.d.avatarTs = Date.now(); } }
  /* land on the main menu with a flashing arrow at the box for the path they picked (they choose when to go in) */
  saveProg(); go("home", { pointGo: R ? R[4] : "gen" });
  setTimeout(function () { var el = document.querySelector(".route.pointed"); if (el) try { el.scrollIntoView({ block: "center", behavior: "smooth" }); } catch (e) {} }, 60);
}

