function applyCode(code) {
  code = String(code || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, ""); PRO.code = code;
  if (!code) return;
  var db = Prog.db || Dex.db;
  if (!db) { PRO.msg = "School codes need an internet connection and a DrugBug account. Try again online."; return drawPaywall(); }
  PRO.msg = "Checking code…"; drawPaywall();
  db.doc("licenses/" + code).get().then(function (s) {
    var L = s.exists ? s.data() : null;
    if (!L || !L.until || L.until < Date.now()) { PRO.msg = "That code isn't active. Check with your instructor."; return drawPaywall(); }
    Prog.d.license = { code: code, until: L.until, org: L.org || "" }; saveProg();
    if (Prog.uid) db.doc("licenseUse/" + code + "_" + Prog.uid).set({ code: code, uid: Prog.uid, ts: Date.now() }).catch(function () {});
    PRO.msg = ""; PRO.open = false; closePaywall(); S.proMsg = "Code applied: DrugBug Pro through " + new Date(L.until).toLocaleDateString() + (L.org ? " from " + L.org : "") + "."; render();
  }).catch(function () { PRO.msg = "Could not check that code right now."; drawPaywall(); });
}
