var ALT_CORE = ["beta blocker", "beta-blocker", "cephalosporin", "penicillin", "carbapenem", "fluoroquinolone", "macrolide", "tetracycline", "aminoglycoside", "nsaid", "opioid", "benzodiazepine", "ssri", "snri", "statin", "hmg-coa", "ace inhibitor", "angiotensin-converting", "angiotensin ii receptor", "factor xa", "thrombin inhibitor", "sulfonylurea", "5-ht3", "h1 ", "h1-", "h2 ", "h2-", "proton pump", "dihydropyridine", "loop diuretic", "thiazide", "corticosteroid", "glucocorticoid", "neuromuscular block", "bisphosphonate", "tricyclic", "triptan", "glp-1", "sglt2", "dpp-4", "barbiturate", "local anesthetic", "carbonic anhydrase", "leukotriene", "mast cell", "insulin", "nitrate", "cardiac glycoside", "low molecular weight heparin", "p2y12"];
function altCore(d) { if (d._core) return d._core; var t = " " + (get(d, 0, 3) + " " + get(d, 0, 4)).toLowerCase() + " "; var antag = /opioid (receptor )?antagonist|mu-opioid (receptor )?antagonist/.test(t);
  return (d._core = ALT_CORE.filter(function (k) { if (k === "opioid" && antag) return false; var i = t.indexOf(k); while (i >= 0) { if (!/[a-z-]/.test(t.charAt(i - 1))) return true; i = t.indexOf(k, i + 1); } return false; }).map(function (k) { return k.replace(/[ -]$/, "").replace("beta-blocker", "beta blocker").replace("angiotensin-converting", "ace inhibitor"); })); }
