function altJac(a, b) { if (!a.length || !b.length) return 0; var A = {}, n = 0, u = {}; a.forEach(function (w) { A[w] = 1; u[w] = 1; }); b.forEach(function (w) { if (A[w] && !u["#" + w]) { n++; u["#" + w] = 1; } u[w] = 1; }); return n / Object.keys(u).filter(function (k) { return k[0] !== "#"; }).length; }
