var ALT_TSTOP = { pain: 1, fever: 1, other: 1, prevention: 1, treatment: 1, prophylaxis: 1, adjunct: 1, "off-label": 1, maintenance: 1, acute: 1, chronic: 1 };
function altFam(id) { return (DB.FAM || []).filter(function (f) { return f.members.some(function (m) { return m.id === id; }); }); }
function altFamDiff(famList, id) { var out = ""; famList.forEach(function (f) { f.members.forEach(function (m) { if (m.id === id && !out) out = (m.key ? m.key + ". " : "") + (m.diff || ""); }); }); return out; }
