var PB_USES_ES = { aad: "Diarrea por antibióticos", cdiff: "C. difficile", "peds-diarrhea": "Diarrea aguda en niños", travel: "Diarrea del viajero", ibs: "Síndrome de intestino irritable", colic: "Cólico del lactante", nec: "Bebés prematuros (ECN)", ibd: "Colitis, pouchitis, Crohn", hpylori: "Tratamiento de H. pylori", vaginal: "Salud vaginal y urinaria", oral: "Boca y garganta", allergy: "Eccema y alergia", resp: "Resfriados e infecciones respiratorias", constipation: "Estreñimiento", mood: "Estrés, ánimo y sueño", metabolic: "Peso, glucosa y lípidos", lactose: "Digestión de lactosa", general: "Comodidad digestiva general" };
