function pbUseName(u) { if (lang() === "es" && PB_USES_ES[u]) return PB_USES_ES[u]; var x = PB_USES.filter(function (y) { return y[0] === u; })[0]; return x ? x[1] : u; }
function pbEv(ev) { var x = PB_EV[ev] || [ev, ev]; return '<span class="pbev pbev-' + esc(ev) + '">' + esc(lang() === "es" ? x[1] : x[0]) + '</span>'; }
function pbMatch(p, q) { q = q.toLowerCase(); return [nameOf(p.id), p.strain, p.old, p.products, p.kind].join(" ").toLowerCase().indexOf(q) >= 0; }
