    CONDS.forEach(function (g) {
      var L = g[1].filter(function (x) { return !q || x[1].toLowerCase().indexOf(q) >= 0; }); if (!L.length) return;
      c += '<h3 class="eh small">' + esc(g[0]) + '</h3><div class="chips">' + L.map(function (x) { return '<button class="chip" data-cond="' + x[0] + '">' + esc(x[1]) + '</button>'; }).join("") + '</div>';
    });
