  pkCount(); var side = Math.random() < .5 ? "l" : "r", el = document.createElement("button");
  el.className = "peeker pk-" + side; el.type = "button"; el.style.top = (28 + Math.random() * 46).toFixed(0) + "vh";
  el.setAttribute("aria-label", (lang() === "es" ? "¡Atrapa a " : "Catch ") + pkName(p) + (lang() === "es" ? "!" : "!"));
