  var k = el.getAttribute("data-xk");
  if (e.key === "Backspace" && !el.value) { e.preventDefault(); gmCrossMove(k, -1); var q = document.activeElement; if (q && q.getAttribute("data-xk")) { q.value = ""; GM.fill[q.getAttribute("data-xk")] = ""; } }
  else if (e.key === "ArrowRight" || e.key === "ArrowLeft") { GM.dir = "a"; gmCrossMove(k, e.key === "ArrowRight" ? 1 : -1); e.preventDefault(); }
  else if (e.key === "ArrowDown" || e.key === "ArrowUp") { GM.dir = "d"; gmCrossMove(k, e.key === "ArrowDown" ? 1 : -1); e.preventDefault(); }
