/* sounds (follow Settings → Sound effects) */
function gfxSnd(kind) {
  if (typeof SET !== "function" || !SET().sfx) return;
  try {
    var AC = window.AudioContext || window.webkitAudioContext; if (!AC) return;
    var c = SFX.ctx || (SFX.ctx = new AC()), t = c.currentTime;
    function tone(type, f0, f1, at, dur, v) { var o = c.createOscillator(), g = c.createGain(); o.type = type; o.frequency.setValueAtTime(f0, t + at); if (f1) o.frequency.exponentialRampToValueAtTime(f1, t + at + dur); g.gain.setValueAtTime(0.0001, t + at); g.gain.exponentialRampToValueAtTime(v || 0.15, t + at + 0.01); g.gain.exponentialRampToValueAtTime(0.0001, t + at + dur); o.connect(g); g.connect(c.destination); o.start(t + at); o.stop(t + at + dur + 0.02); }
    function noise(at, dur, v, fq) { var n = c.sampleRate * dur, b = c.createBuffer(1, n, c.sampleRate), d = b.getChannelData(0); for (var i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n); var s = c.createBufferSource(), f = c.createBiquadFilter(), g = c.createGain(); s.buffer = b; f.type = "lowpass"; f.frequency.value = fq || 900; g.gain.value = v || 0.25; s.connect(f); f.connect(g); g.connect(c.destination); s.start(t + at); }
    if (kind === "pop") tone("sine", 520, 1100, 0, 0.09, 0.16);
    else if (kind === "chomp") { noise(0, 0.07, 0.35, 700); tone("square", 140, 70, 0, 0.08, 0.08); noise(0.1, 0.06, 0.3, 600); }
    else if (kind === "chirp") { tone("sine", 3200, 4200, 0, 0.04, 0.06); tone("sine", 3400, 4400, 0.07, 0.04, 0.06); }
    else if (kind === "buzz") { var o = c.createOscillator(), g = c.createGain(), l = c.createOscillator(), lg = c.createGain(); o.type = "sawtooth"; o.frequency.value = 190; l.frequency.value = 28; lg.gain.value = 25; l.connect(lg); lg.connect(o.frequency); g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.06, t + 0.05); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.8); o.connect(g); g.connect(c.destination); o.start(t); l.start(t); o.stop(t + 0.85); l.stop(t + 0.85); }
    else if (kind === "burp") { tone("sawtooth", 110, 70, 0, 0.35, 0.12); noise(0, 0.3, 0.12, 300); }
    else if (kind === "whoosh") noise(0, 0.45, 0.2, 2400);
    else if (kind === "tick") tone("square", 1800, 0, 0, 0.03, 0.05);
    else if (kind === "win") [523, 659, 784, 1047].forEach(function (f, i) { tone("triangle", f, 0, i * 0.09, 0.18, 0.13); });
    else if (kind === "zip") tone("sine", 400, 1600, 0, 0.18, 0.08);
    else if (kind === "sparkle") [1568, 2093, 2637].forEach(function (f, i) { tone("sine", f, 0, i * 0.06, 0.12, 0.07); });
  } catch (e) {}
}

/* your own bug pops up and dances */
function gfxCheer() {
  if (typeof myBugArt !== "function") return;
  var e = gfxAdd('<div class="gfxcheer">' + myBugArt("gfxbug", "joy") + '<span class="gfxsay">Nice!</span></div>', "", 2600);
  gfxSnd("win");
}
/* "New best!" banner with falling leaf confetti */
function gfxBest(text) {
  gfxAdd('<div class="gfxbest">' + esc(text || "New best!") + '</div>', "", 2800);
  if (gfxReduce()) return;
  var cols = ["#22c55e", "#84cc16", "#16a34a", "#facc15", "#f97316"], html = "";
  for (var i = 0; i < 26; i++) html += '<i class="leaf" style="left:' + (Math.random() * 100).toFixed(1) + '%;animation-delay:' + (Math.random() * 0.8).toFixed(2) + 's;animation-duration:' + (1.8 + Math.random() * 1.4).toFixed(2) + 's;background:' + cols[i % cols.length] + ';--r:' + Math.round(Math.random() * 720 - 360) + 'deg"></i>';
  gfxAdd(html, "position:fixed;inset:0", 3600);
}
/* Memory: a matched card cracks like an egg and a tiny bug flutters out */
function gfxHatch(r) {
  if (!r || gfxReduce()) return;
  gfxAdd('<div class="egg"><i class="eh l"></i><i class="eh r"></i></div>', "position:fixed;left:" + (r.cx - 22) + "px;top:" + (r.cy - 26) + "px", 900);
  var b = gfxAdd('<div class="flap">' + GFX_BUG + '</div>', "position:fixed;left:0;top:0", 2000), dx = (Math.random() < .5 ? -1 : 1) * (60 + Math.random() * 80);
  gfxFly(b, function (t) { return { x: r.cx - 15 + dx * t + Math.sin(t * 12) * 10, y: r.cy - 12 - 260 * t, o: t > .8 ? (1 - t) * 5 : 1 }; }, 1600);
}
/* Memory: fireflies rise from every card */
function gfxFireflies(rects) {
  if (gfxReduce()) return;
  rects.forEach(function (r, k) {
    var f = gfxAdd('<i class="ffly"></i>', "position:fixed;left:0;top:0", 3200), ph = Math.random() * 6;
    setTimeout(function () { gfxFly(f, function (t) { return { x: r.cx + Math.sin(t * 9 + ph) * 26, y: r.cy - 340 * t, o: t < .1 ? t * 10 : t > .75 ? (1 - t) * 4 : 1 }; }, 2400); }, k * 90);
  });
}
/* Quick Match: a silk thread zips between a matched pair */
function gfxSilk(a, b) {
  if (!a || !b) return;
  var x1 = a.x + a.w, y1 = a.cy, x2 = b.x, y2 = b.cy;
  gfxAdd('<svg class="silk" width="100%" height="100%"><line x1="' + x1 + '" y1="' + y1 + '" x2="' + x2 + '" y2="' + y2 + '"/><circle cx="' + x1 + '" cy="' + y1 + '" r="3"/><circle cx="' + x2 + '" cy="' + y2 + '" r="3"/></svg>', "position:fixed;inset:0", 1400);
  gfxSnd("zip");
}
/* Quick Match: the threads become a web and a spider drops in to say well done */
function gfxWeb(r) {
  if (!r) return;
  var cx = r.cx, cy = r.cy, R = Math.min(r.w, r.h) / 2 + 20, s = "";
  for (var k = 0; k < 12; k++) { var a = k * Math.PI / 6; s += '<line x1="' + cx + '" y1="' + cy + '" x2="' + (cx + Math.cos(a) * R) + '" y2="' + (cy + Math.sin(a) * R) + '"/>'; }
  for (var j = 1; j <= 5; j++) { var p = []; for (k = 0; k <= 12; k++) { a = k * Math.PI / 6; var rr = R * j / 5 * (k % 2 ? .93 : 1); p.push((cx + Math.cos(a) * rr).toFixed(1) + "," + (cy + Math.sin(a) * rr).toFixed(1)); } s += '<polyline points="' + p.join(" ") + '"/>'; }
  gfxAdd('<svg class="web" width="100%" height="100%">' + s + '</svg>', "position:fixed;inset:0", 3000);
  if (gfxReduce()) return;
  var sp = gfxAdd('<div class="spider"><i class="thread"></i>' + GFX_SPIDER + '<span class="gfxsay">Great job!</span></div>', "position:fixed;left:" + (cx - 28) + "px;top:0", 3000);
  gfxFly(sp, function (t) { var d = t < .35 ? t / .35 : t > .8 ? (1 - t) / .2 : 1; return { x: 0, y: (cy - 40) * d - 60 * (1 - d) }; }, 2900);
}
/* Quick Match wrong pick: an angry bee buzzes around the card */
function gfxBee(r) {
  if (!r) return; gfxSnd("buzz"); if (gfxReduce()) return;
  var b = gfxAdd('<div class="flap fast">' + GFX_BEE + '</div>', "position:fixed;left:0;top:0", 1100);
  gfxFly(b, function (t) { var a = t * Math.PI * 4; return { x: r.cx - 17 + Math.cos(a) * (r.w / 2 + 6), y: r.cy - 13 + Math.sin(a) * (r.h / 2 + 10), a: Math.cos(a) * 20 }; }, 1000);
}
/* Crossword: a ladybug walks along a finished word */
function gfxLadybug(cells) {
  if (!cells.length || gfxReduce()) return;
  var L = gfxAdd('<div class="lady">' + GFX_LADY + '</div>', "position:fixed;left:0;top:0", 2600), n = cells.length, horiz = n > 1 && Math.abs(cells[1].cy - cells[0].cy) < 3;
  gfxFly(L, function (t) { var f = t * (n - 1), i = Math.min(n - 2, Math.floor(f)), u = f - i, a = cells[i], b = cells[Math.min(n - 1, i + 1)] || a; return { x: a.cx + (b.cx - a.cx) * u - 12, y: a.cy + (b.cy - a.cy) * u - 12, a: horiz ? 90 : 180, o: t > .9 ? (1 - t) * 10 : 1 }; }, Math.max(900, n * 230));
}
/* Crossword solved: the grid wraps into a cocoon and a butterfly flutters off */
function gfxButterfly(r) {
  if (!r) return; gfxSnd("whoosh");
  var cx = r.cx, cy = r.cy;
  gfxAdd('<div class="cocoon"></div>', "position:fixed;left:" + (cx - 30) + "px;top:" + (cy - 45) + "px", 1300);
  if (gfxReduce()) return;
  setTimeout(function () {
    var b = gfxAdd('<div class="flap bfly">' + gfxButterflySvg("#f472b6", "#a78bfa") + '</div>', "position:fixed;left:0;top:0", 4200), ang = -Math.PI / 2 + (Math.random() - .5) * 2.2, ph = Math.random() * 6, D = Math.max(window.innerWidth, window.innerHeight) + 120;
    gfxSnd("sparkle");
    gfxFly(b, function (t) { var d = D * t * t * 0.9 + 40 * t; return { x: cx - 40 + Math.cos(ang) * d + Math.sin(t * 10 + ph) * 30, y: cy - 30 + Math.sin(ang) * d + Math.cos(t * 7 + ph) * 18, s: Math.min(1, t * 6 + .2), a: Math.sin(t * 9) * 15 }; }, 3600);
  }, 1000);
}
/* Class Blitz streak: a dragonfly zooms across */
function gfxDragonfly() {
  gfxSnd("whoosh"); if (gfxReduce()) return;
  var y = 120 + Math.random() * (window.innerHeight * .5), W = window.innerWidth, ltr = Math.random() < .5;
  var d = gfxAdd('<div class="flap fast"' + (ltr ? "" : ' style="transform:scaleX(-1)"') + '>' + GFX_FLY + '</div>', "position:fixed;left:0;top:0", 1400);
  gfxFly(d, function (t) { return { x: ltr ? -120 + (W + 240) * t : W + 20 - (W + 240) * t, y: y + Math.sin(t * 8) * 30 }; }, 1200);
}
/* sparkle burst (golden bug) */
function gfxSparkle(r) {
  if (!r) return; gfxSnd("sparkle"); if (gfxReduce()) return;
  for (var k = 0; k < 10; k++) (function (k) { var s = gfxAdd('<i class="spk"></i>', "position:fixed;left:0;top:0", 900), a = k * Math.PI / 5; gfxFly(s, function (t) { return { x: r.cx + Math.cos(a) * 60 * t, y: r.cy + Math.sin(a) * 60 * t, o: 1 - t, s: 1 - t * .5 }; }, 800); })(k);
}

/* ---------- Wandering stick bug: now and then a stick insect wanders across the screen from any side.
   Tap him for sticks: he stops, turns to look at you, clearly bothered ("Hey!"), then sprints off. ---------- */
var SB = { t: null, el: null, raf: 0, path: null, pos: null, ang: 0, state: "", t0: 0 };
var SB_STICKS = 5, SB_DAY_MAX = 3;
function sbCalm() {
  if (document.hidden) return false;
  if (typeof needDisc === "function" && needDisc()) return false;
  if (typeof agreeRec === "function" && !agreeRec()) return false;
  if (typeof tourDone === "function" && !tourDone()) return false;
  if (typeof topLayerOpen === "function" && topLayerOpen()) return false;
  if (S.sheet || S.sess || S.mupop) return false;
  if (S.tab === "prep" || S.tab === "scenarios" || S.tab === "tools" || S.tab === "games" || S.tab === "calc") return false; /* never during a test or game */
  return true;
}
function sbArt(face, look) {
  if (face) return '<svg class="sbface" viewBox="0 0 70 70" aria-hidden="true"><path d="M26 14 Q18 2 10 0 M44 14 Q52 2 60 0" stroke="#6b4423" stroke-width="2.5" fill="none" stroke-linecap="round"/><ellipse cx="35" cy="36" rx="20" ry="22" fill="#a0703c" stroke="#5b3a1a" stroke-width="2.5"/><ellipse cx="26" cy="34" rx="6" ry="5" fill="#fff"/><ellipse cx="44" cy="34" rx="6" ry="5" fill="#fff"/><circle cx="27" cy="35" r="2.6" fill="#1b1430"/><circle cx="43" cy="35" r="2.6" fill="#1b1430"/><path d="M19 29 L32 32 M51 29 L38 32" stroke="#3b230d" stroke-width="3" stroke-linecap="round"/><path d="M27 49 Q35 44 43 49" stroke="#3b230d" stroke-width="2.6" fill="none" stroke-linecap="round"/><path d="M52 20 q3 5 0 7 q-3 -2 0 -7z" fill="#7dd3fc"/></svg>';
  /* side view: long twig body, small head, long antennae, six jointed legs (two sets that swing in turn) */
  var leg = function (x, k) { return '<g class="sbleg ' + (k % 2 ? "b" : "a") + '" style="transform-origin:' + x + 'px 30px"><path d="M' + x + ' 30 L' + (x + 6) + ' 20 L' + (x + 12) + ' 44" stroke="#b07a45" stroke-width="2.8" fill="none" stroke-linejoin="round" stroke-linecap="round"/></g>'; };
  return '<svg class="sbside" viewBox="0 0 150 50" aria-hidden="true">' + leg(30, 0) + leg(58, 1) + leg(88, 0) +
    '<path d="M8 31 L120 29" stroke="#a87442" stroke-width="8" stroke-linecap="round"/><path d="M20 29 L110 27" stroke="#d6a56b" stroke-width="2.5" stroke-linecap="round" opacity=".8"/>' +
    '<g class="sbhead' + (look ? ' up' : '') + '"><ellipse cx="124" cy="28" rx="8" ry="6" fill="#a87442"/><circle cx="127" cy="26" r="2" fill="#1b1430"/><path d="M130 25 Q140 10 149 4 M129 27 Q142 18 150 16" stroke="#b07a45" stroke-width="1.8" fill="none" stroke-linecap="round"/></g>' +
    leg(40, 1) + leg(70, 0) + leg(98, 1) + '</svg>';
}
function sbSchedule(first) {
  clearTimeout(SB.t);
  var lo = first ? 90 : 420, hi = first ? 300 : 900; /* seconds: first visit 1.5-5 min in, then every 7-15 min */
  if (window.__SB_FAST) { lo = 1; hi = 2; }
  SB.t = setTimeout(sbShow, (lo + Math.random() * (hi - lo)) * 1000);
}
function sbLeft() { var P = Prog.d, t = typeof today === "function" ? today() : new Date().toDateString(); var d = P.stickBug || {}; return d.day === t ? Math.max(0, SB_DAY_MAX - (d.n || 0)) : SB_DAY_MAX; }
/* a point just past a random screen edge (0 top, 1 right, 2 bottom, 3 left) */
function sbEdge(W, H, not) {
  var e; do { e = Math.floor(Math.random() * 4); } while (e === not);
  var m = 50, r = Math.random();
  return { e: e, x: e === 1 ? W + m : e === 3 ? -m : 30 + r * (W - 60), y: e === 0 ? -m : e === 2 ? H + m : 60 + r * (H - 120) };
}
function sbPath(p0, p2, bend) {
  var dx = p2.x - p0.x, dy = p2.y - p0.y, L = Math.hypot(dx, dy) || 1;
  var k = (Math.random() - .5) * bend * L; /* gentle sideways curve */
  var p1 = { x: (p0.x + p2.x) / 2 - dy / L * k, y: (p0.y + p2.y) / 2 + dx / L * k };
  return { p0: p0, p1: p1, p2: p2, len: L * 1.1, u: 0, flip: p2.x < p0.x }; /* flip keeps his legs underneath when heading left */
}
function sbAt(P, u) {
  var a = 1 - u;
  return { x: a * a * P.p0.x + 2 * a * u * P.p1.x + u * u * P.p2.x, y: a * a * P.p0.y + 2 * a * u * P.p1.y + u * u * P.p2.y,
    dx: 2 * a * (P.p1.x - P.p0.x) + 2 * u * (P.p2.x - P.p1.x), dy: 2 * a * (P.p1.y - P.p0.y) + 2 * u * (P.p2.y - P.p1.y) };
}
function sbShow() {
  if (SB.el || !sbCalm() || !sbLeft()) return sbSchedule(false);
  var W = window.innerWidth, H = window.innerHeight, el = document.createElement("button");
  el.className = "stickbug walk"; el.type = "button"; el.setAttribute("aria-label", "A stick bug is walking by. Tap him for sticks.");
  el.innerHTML = sbArt(false);
  var a = sbEdge(W, H, -1), z = sbEdge(W, H, a.e);
  SB.path = sbPath(a, z, .5); SB.state = "walk"; SB.el = el; SB.ang = 0; SB.pos = a;
  el.addEventListener("click", sbTap);
  document.body.appendChild(el);
  var last = performance.now();
  (function step(now) {
    if (!SB.el) return;
    var dt = Math.min(0.05, (now - last) / 1000); last = now;
    var v = SB.state === "run" ? 420 : SB.state === "walk" ? 34 : 0, P = SB.path;
    if (v) {
      P.u = Math.min(1, P.u + v * dt / P.len);
      var q = sbAt(P, P.u); SB.pos = q;
      if (q.dx || q.dy) SB.ang = Math.atan2(q.dy, q.dx) * 180 / Math.PI;
      el.style.transform = "translate(" + (q.x - 38).toFixed(1) + "px," + (q.y - 14).toFixed(1) + "px) rotate(" + SB.ang.toFixed(1) + "deg)" + (P.flip ? " scaleY(-1)" : "");
      if (P.u >= 1) return sbGone();
    }
    if (SB.state === "walk" && !sbCalm()) sbRun(); /* he leaves quietly if a test or game opens */
    SB.raf = requestAnimationFrame(step);
  })(last);
}
/* off he goes toward any edge, in a near-straight line */
function sbRun() {
  var W = window.innerWidth, H = window.innerHeight, p = SB.pos, z = sbEdge(W, H, -1);
  SB.path = sbPath({ x: p.x, y: p.y }, z, .15); SB.state = "run";
  if (SB.el) { SB.el.classList.remove("look"); SB.el.classList.add("walk", "run"); }
}
function sbBadge() {
  var p = SB.pos || { x: 0, y: 0 }, b = document.createElement("span");
  b.className = "sbgot"; b.textContent = "+" + SB_STICKS + " sticks";
  b.style.left = Math.max(8, Math.min(window.innerWidth - 90, p.x - 40)) + "px"; b.style.top = Math.max(8, Math.min(window.innerHeight - 40, p.y - 40)) + "px";
  document.body.appendChild(b); setTimeout(function () { if (b.parentNode) b.parentNode.removeChild(b); }, 1500);
}
function sbTap(e) {
  e.preventDefault(); e.stopPropagation();
  var el = SB.el; if (!el || SB.state !== "walk") return;
  SB.state = "look";
  var P = Prog.d, t = typeof today === "function" ? today() : new Date().toDateString(), d = P.stickBug && P.stickBug.day === t ? P.stickBug : { day: t, n: 0 };
  d.n++; P.stickBug = d; earn(SB_STICKS); if (typeof saveProg === "function") saveProg();
  if (typeof gfxSnd === "function") gfxSnd("pop");
  /* he turns to look at you, bothered */
  el.classList.remove("walk"); el.classList.add("look");
  el.innerHTML = sbArt(false, true); sbBadge();
  setTimeout(function () {
    if (SB.el !== el) return;
    /* and he runs off in any direction */
    el.innerHTML = sbArt(false); sbRun();
    if (typeof gfxSnd === "function") gfxSnd("whoosh");
    if (typeof render === "function" && S.view !== "admin") setTimeout(render, 300);
  }, 1500);
}
function sbGone() { cancelAnimationFrame(SB.raf); if (SB.el && SB.el.parentNode) SB.el.parentNode.removeChild(SB.el); SB.el = null; SB.state = ""; sbSchedule(false); }
document.addEventListener("visibilitychange", function () { if (document.hidden && SB.el) sbGone(); });
sbSchedule(true);

/* ---------- Ratings and ideas ----------
   Rating: after a few good study sessions the app asks iOS / Google Play for their own rating box
   (the store decides whether it actually appears; Apple shows it at most 3 times a year). Never during a quiz or game.
   Ideas: a short form that opens the person's email app with their suggestion filled in, addressed to the DrugBug inbox. */
var RV_MIN_SESS = 5, RV_GAP_DAYS = 120;
var IDEA_TYPES = ["General feedback", "Field Medic: comment, request or thought", "Something is wrong (a bug)", "A content correction", "A feature I would like", "A drug to add", "A topic, exam or specialty to cover", "Something that is confusing", "Other"];
var ID = { open: null, sent: false, err: "" };
/* what senders can and cannot include (owner, Oct 28 2026). Shown before anything is sent. */
var FB_LIMITS = [
  ["No patient information", "No names, dates of birth, record numbers, photos or any detail that could identify a patient (protected health information under HIPAA)."],
  ["No classified or sensitive operational information", "No classified or controlled unclassified information (CUI), and nothing covered by operations security (OPSEC): unit names, locations, movements, mission or equipment details."],
  ["Only what you have the right to share", "No agency protocols, internal documents, copyrighted material or other people's work without permission."],
  ["Nothing about other people, nothing unlawful", "No personal information about anyone else, and nothing harassing, threatening, defamatory or illegal."],
  ["Not for emergencies or medical advice", "Feedback is not monitored around the clock and DrugBug does not give individual medical advice. In an emergency, call 911."],
  ["Use of your feedback", "By sending, you agree that Volare Media LLC may use, change and publish your suggestions to improve DrugBug, without payment, credit or any obligation to you."],
  ["Privacy", "Feedback travels by email, so it is only as private as your email account. Your address and message are handled under the DrugBug Privacy Policy."]
];
function fbLimitsHTML(withBox) {
  return '<div class="fblimits"><strong>Before you send</strong><ul>' + FB_LIMITS.map(function (x) { return '<li><b>' + esc(x[0]) + '.</b> ' + esc(x[1]) + '</li>'; }).join("") + '</ul>' +
    (withBox ? '<label class="fbok"><input type="checkbox" id="idok"' + (ID.ok ? " checked" : "") + '> I have read this, and my message follows these limits.</label>' : '') + '<p class="muted small"><button class="linkish" data-legal="terms">Terms of Use</button> · <button class="linkish" data-legal="privacy">Privacy Policy</button></p></div>';
}
var idlg = document.createElement("div"); idlg.id = "idlg"; idlg.className = "sheet rsheet"; idlg.hidden = true; document.body.appendChild(idlg);

function ideaEmail() { var c = window.DRUGBUG_CONFIG || {}; return c.supportEmail || CONTACT; }
function isAndroid() { return !!window.DrugBugAndroid; }
function hasReview() { return !!(window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.review); }
/* the store page where people can write a review on their own */
function rateUrl() {
  if (isAndroid()) return "https://play.google.com/store/apps/details?id=com.volaremedia.drugbug";
  var id = String((window.DRUGBUG_CONFIG || {}).appStoreId || "").replace(/\D/g, "");
  return NATIVE && id ? "https://apps.apple.com/app/id" + id + "?action=write-review" : "";
}
/* called when a study session finishes with a good score */
function rateMaybe(sc) {
  try {
    if (!hasReview() || !sc || sc.n < 5 || sc.pct < 70) return;
    var r = Prog.d.rv || (Prog.d.rv = { s: 0, last: 0 }); r.s = (r.s || 0) + 1; saveProg();
    if (r.s < RV_MIN_SESS || (r.last && Date.now() - r.last < RV_GAP_DAYS * 864e5)) return;
    setTimeout(function () {
      if (S.sess && !S.sess.result) return; /* a new quiz already started */
      if (topLayerOpen()) return;
      r.last = Date.now(); saveProg();
      try { window.webkit.messageHandlers.review.postMessage({}); } catch (e) {}
    }, 1800);
  } catch (e) {}
}
/* Settings row: rate + send ideas */
function ideasRow() {
  var u = rateUrl();
  return setRow("Enjoying DrugBug?", (u ? "Ratings help other students find the app. " : "") + "Feedback and ideas go straight to the DrugBug team.",
    (u ? '<a class="btn small ghost" href="' + esc(u) + '" target="_blank" rel="noopener">Rate DrugBug</a> ' : '') + '<button class="btn small ghost" data-idea="1">Send feedback</button>');
}
function openIdeas(type) { ID.open = { type: type || IDEA_TYPES[0], text: "" }; ID.sent = false; ID.err = ""; ID.ok = false; S.menu = false; drawIdeas(); idlg.hidden = false; var f = $("#idtext", idlg); if (f) f.focus(); }
function closeIdeas() { idlg.hidden = true; idlg.innerHTML = ""; ID.open = null; }
function ideaMail(o) {
  var lv = ctxKey(), lvn = lv === "gen" ? "All drugs" : lv ? levelObj(lv).name : "Home";
  var plat = isAndroid() ? "Android" : NATIVE ? "iPhone/iPad" : "Web";
  var body = o.text + "\n\n---\nType: " + o.type + "\nDrugBug " + APP_VERSION + " · " + plat + " · " + lvn + "\n";
  return "mailto:" + ideaEmail() + "?subject=" + encodeURIComponent("DrugBug feedback: " + o.type) + "&body=" + encodeURIComponent(body);
}
function drawIdeas() {
  var o = ID.open; if (!o) return;
  var c = '<div class="panel" role="dialog" aria-modal="true" aria-label="Send feedback" tabindex="-1"><div class="navrow"><h2 class="dname">Send feedback</h2><span class="spacer"></span><button class="iconbtn" data-iact="close">Close</button></div>';
  if (ID.sent) return idlg.innerHTML = c + '<div class="presult good" role="status">Your email app opened with your message filled in. Tap Send there to reach the DrugBug team. Thank you!</div>' +
    '<p class="muted small">Email app did not open? Write to <a href="mailto:' + esc(ideaEmail()) + '">' + esc(ideaEmail()) + '</a>.</p><div class="actions"><button class="btn" data-iact="close">Done</button></div></div>';
  c += '<p class="muted">Feedback, bugs, corrections and ideas go straight to the DrugBug team. Every message is read.</p>';
  c += '<div class="pform"><label>What is it about?<select class="pinput" id="idtype">' + IDEA_TYPES.map(function (t) { return '<option' + (o.type === t ? " selected" : "") + '>' + esc(t) + '</option>'; }).join("") + '</select></label>';
  c += '<label>Your message<textarea class="pinput" id="idtext" rows="6" maxlength="2000" placeholder="For example: the dose card for X looks wrong, or add a quiz on Y">' + esc(o.text) + '</textarea></label>' + fbLimitsHTML(true);
  if (ID.err) c += '<div class="presult" role="alert">' + esc(ID.err) + '</div>';
  c += '<p class="muted small">This opens your email app, so the team can reply to you there. Sent to ' + esc(ideaEmail()) + '.</p>';
  c += '<div class="actions"><button class="btn" data-iact="send">Write email</button><button class="btn ghost" data-iact="close">Cancel</button></div></div>';
  idlg.innerHTML = c + '</div>';
}
function sendIdea() {
  var o = ID.open; o.type = $("#idtype", idlg).value; o.text = $("#idtext", idlg).value.trim();
  if (o.text.length < 3) { ID.err = "Add a few words to your message."; return drawIdeas(); }
  if (!($("#idok", idlg) || {}).checked) { ID.err = "Please confirm that your message follows the limits above."; return drawIdeas(); }
  ID.err = ""; window.location.href = ideaMail(o); ID.sent = true; drawIdeas();
}
idlg.addEventListener("click", function (e) {
  if (e.target === idlg) return closeIdeas();
  var t = e.target.closest("[data-iact]"); if (!t) return;
  var a = t.getAttribute("data-iact"); if (a === "close") return closeIdeas(); if (a === "send") return sendIdea();
});
idlg.addEventListener("input", function (e) { if (ID.open && e.target.id === "idtext") ID.open.text = e.target.value; });
idlg.addEventListener("change", function (e) { if (ID.open && e.target.id === "idok") ID.ok = e.target.checked; if (ID.open && e.target.id === "idtype") ID.open.type = e.target.value; });
document.addEventListener("keydown", function (e) { if (e.key === "Escape" && ID.open) closeIdeas(); });

