  c += '<header class="dishead"><span class="dsys">' + esc(e.sys) + '</span><h2>🪱 ' + esc(e.name) + '</h2>' + (e.aka && e.aka.length ? '<p class="dnote">Also called: ' + esc(e.aka.join(", ")) + '</p>' : '') + '</header>';
