  s += '<path d="M84 50 Q66 22 76 8 Q80 28 94 40 M116 50 Q134 22 124 8 Q120 28 106 40" stroke="#1b1430" stroke-width="7" fill="none" stroke-linecap="round"/>';
  s += legs("#1b1430", 6);
  s += '<ellipse cx="100" cy="142" rx="33" ry="47" fill="url(#' + id + 'g)"/><path d="M100 120 V188" stroke="#1b1430" stroke-width="3"/>';
  /* plate carrier, cut to the slim torso */
  var t = 100;
  s += '<path d="M76 ' + t + ' H124 Q132 ' + (t + 30) + ' 130 ' + (t + 64) + ' Q100 ' + (t + 76) + ' 70 ' + (t + 64) + ' Q68 ' + (t + 30) + ' 76 ' + t + 'Z" fill="#8b7a55" stroke="#3a3220" stroke-width="3" stroke-linejoin="round"/>';
  s += '<path d="M78 ' + (t - 2) + ' L80 ' + (t - 12) + ' H90 L90 ' + (t + 2) + ' M122 ' + (t - 2) + ' L120 ' + (t - 12) + ' H110 L110 ' + (t + 2) + '" fill="#7a6a47" stroke="#3a3220" stroke-width="2.5" stroke-linejoin="round"/>';
  s += '<rect x="80" y="' + (t + 8) + '" width="40" height="30" rx="5" fill="#7a6a47" stroke="#3a3220" stroke-width="2"/>';
  s += '<path d="M83 ' + (t + 16) + ' H117 M83 ' + (t + 23) + ' H117 M83 ' + (t + 30) + ' H117" stroke="#5c4f33" stroke-width="2" stroke-dasharray="4 3"/>';
  s += '<rect x="84" y="' + (t + 10) + '" width="15" height="5" rx="2" fill="#16181a"/><rect x="95" y="' + (t + 9.5) + '" width="5" height="6.5" rx="1.5" fill="#d23b3b"/>';
  s += '<rect x="104" y="' + (t + 10) + '" width="13" height="10" rx="2" fill="#6b5c3c" stroke="#3a3220" stroke-width="1.5"/><rect x="109" y="' + (t + 11.2) + '" width="3.2" height="7.6" fill="#d23b3b"/><rect x="106.8" y="' + (t + 13.4) + '" width="7.6" height="3.2" fill="#d23b3b"/>';
  s += '<rect x="76" y="' + (t + 42) + '" width="14" height="18" rx="3" fill="#6b5c3c" stroke="#3a3220" stroke-width="2"/><rect x="93" y="' + (t + 42) + '" width="14" height="18" rx="3" fill="#6b5c3c" stroke="#3a3220" stroke-width="2"/><rect x="110" y="' + (t + 42) + '" width="14" height="18" rx="3" fill="#6b5c3c" stroke="#3a3220" stroke-width="2"/>';
  s += '<path d="M76 ' + (t + 48) + ' H90 M93 ' + (t + 48) + ' H107 M110 ' + (t + 48) + ' H124" stroke="#3a3220" stroke-width="1.5"/>';
  s += '<rect x="125" y="' + (t + 4) + '" width="8" height="16" rx="2" fill="#24292d" stroke="#0b0f12" stroke-width="1.5"/><path d="M129 ' + (t + 4) + ' L138 ' + (t - 20) + '" stroke="#0b0f12" stroke-width="2.4" stroke-linecap="round"/>';
  /* head, helmet, headset, NVGs down */
  s += '<circle cx="100" cy="' + y + '" r="28" fill="#5aa8ff"/>';
  s += '<path d="M90 ' + (y + 19) + ' Q100 ' + (y + 26) + ' 110 ' + (y + 19) + '" stroke="#1b1430" stroke-width="3.5" fill="none" stroke-linecap="round"/>';
  s += ACC.tachelmet(y) + ACC.headset(y) + ACC.nodsdown(y);
