function blProductPage(i) {
  var p = BL_PRODUCTS[i], q = BL_QUICK[i] || [], x = BL_EXTRA[i] || [];
  var c = '<div class="backrow"><button class="backbtn" data-blt=""><span aria-hidden="true">&larr;</span> Blood</button></div>';
  c += '<header class="blphead"><h2>' + esc(p.n) + '</h2><p>' + esc(p.s) + '</p></header>';
  c += '<section class="dbox" aria-label="Product box"><h3>Product box</h3><div class="dgrid">' + [["Storage", q[0]], ["Shelf life", q[1]], ["Role", q[2]], ["Unit size", x[0]], ["Blood type", x[1]]].filter(function (r) { return r[1]; }).map(function (r) { return '<div class="dcell' + (r[1].length > 60 ? ' wide' : '') + '"><div class="k">' + esc(r[0]) + '</div><div class="v">' + esc(r[1]) + '</div></div>'; }).join("") + '</div></section>';
  c += p.rows.map(function (r) { return '<details class="sec" open><summary>' + esc(r[0]) + '</summary><div class="fields"><p class="blsecp">' + esc(r[1]) + '</p></div></details>'; }).join("");
  var nx = BL_PRODUCTS[i + 1], pv = BL_PRODUCTS[i - 1];
  c += '<div class="blnav">' + (pv ? '<button class="btn small ghost" data-blpi="' + (i - 1) + '">&larr; ' + esc(pv.n) + '</button>' : '<span></span>') + (nx ? '<button class="btn small ghost" data-blpi="' + (i + 1) + '">' + esc(nx.n) + ' &rarr;</button>' : '') + '</div>';
  return c + '<p class="muted small" style="margin-top:12px">Education only. Transfusion follows the theater blood program, the product labels and medical direction.</p>';
}
function fmBloodView() {
  var k = S.blT || "", T = BL_TOPICS.filter(function (x) { return x[0] === k; })[0], c = '';
  if (k === "item" && BL_PRODUCTS[S.blP]) return blProductPage(S.blP);
  if (!T) {
    c += '<section class="blorder"><h3>TCCC order for hemorrhagic shock</h3><ol>' + ["Cold-stored low-titer O whole blood", "Pre-screened low-titer O fresh whole blood", "Plasma, red cells and platelets 1:1:1", "Plasma and red cells 1:1", "Plasma or red cells alone"].map(function (x) { return '<li>' + esc(x) + '</li>'; }).join("") + '</ol><p>Calcium after the first product · TXA within 3 hours · warm every unit · reassess after each unit</p></section>';
    blRegister();
    c += '<h3 class="fmh">Blood and blood products</h3><div class="grid fmtiles2">' + tilesHTML(BLD.map(function (p) { return p.id; }).concat(BLD_REAL.filter(function (id) { return DB.drugs[id]; }))) + '</div>';
    c += '<h3 class="fmh">More on blood</h3><div class="blgrid">' + BL_TOPICS.map(function (t) { return '<button class="bltile" data-blt="' + t[0] + '"><span class="blem" aria-hidden="true">' + t[1] + '</span><strong>' + esc(t[2]) + '</strong><span>' + esc(t[3]) + '</span></button>'; }).join("") + '</div>';
  } else {
    c += blTopicHead(T);
    if (k === "prod_old") c += BL_PRODUCTS.map(function (p, i) { var q = BL_QUICK[i] || [], open = S.blP === i; return '<div class="blprod2' + (open ? ' open' : '') + '"><button class="blph" data-blp="' + i + '" aria-expanded="' + open + '"><span class="blpt"><strong>' + esc(p.n) + '</strong><em>' + esc(p.s) + '</em></span><span class="blchev" aria-hidden="true">' + (open ? '−' : '+') + '</span></button><div class="blfacts"><span>🌡️ ' + esc(q[0] || "") + '</span><span>⏳ ' + esc(q[1] || "") + '</span><span>⭐ ' + esc(q[2] || "") + '</span></div>' + (open ? '<div class="blpbody">' + p.rows.map(function (r) { return '<h4>' + esc(r[0]) + '</h4><p>' + esc(r[1]) + '</p>'; }).join("") + '</div>' : '') + '</div>'; }).join("");
    else if (k === "abo") {
      var g = S.blG || "O", R = BL_ABO.filter(function (r) { return r[0] === g; })[0];
      c += '<p class="muted small">Tap the casualty\'s blood type.</p><div class="blabo">' + BL_ABO.map(function (r) { return '<button data-blg="' + r[0] + '" aria-pressed="' + (r[0] === g) + '">' + r[0] + '</button>'; }).join("") + '</div>';
      c += '<div class="blcards"><div class="blcard big"><strong>Red cells from</strong><p>' + esc(R[1]) + '</p></div><div class="blcard big"><strong>Plasma from</strong><p>' + esc(R[2]) + '</p></div><div class="blcard big"><strong>Their red cells can go to</strong><p>' + esc(R[3]) + '</p></div></div>';
    }
    else if (k === "mt") c += blCards(BL_MT);
    else if (k === "give") c += '<ol class="blsteps">' + BL_GIVE.map(function (x) { return '<li><strong>' + esc(x[0]) + '</strong><p>' + esc(x[1]) + '</p></li>'; }).join("") + '</ol>';
    else if (k === "wbb") c += blCards(BL_WBB);
    else if (k === "rx") c += BL_RX.map(function (r, i) { var open = S.blR === i; return '<div class="blprod2' + (open ? ' open' : '') + '"><button class="blph" data-blr="' + i + '" aria-expanded="' + open + '"><span class="blpt"><strong>' + esc(r[0]) + '</strong><em>' + esc(r[1]) + '</em></span><span class="blchev" aria-hidden="true">' + (open ? '−' : '+') + '</span></button>' + (open ? '<div class="blpbody"><h4>What happens</h4><p>' + esc(r[2]) + '</p><h4>Field response</h4><p>' + esc(r[3]) + '</p></div>' : '') + '</div>'; }).join("");
    else if (k === "labs") c += blCards(BL_LABS);
    else if (k === "evid") c += blCards(BL_EVID) + '<h3 class="fmh">How Europe does it</h3>' + blCards(BL_EU);
    var sc = {}; scopeFor(S.level).ids.forEach(function (id) { sc[id] = 1; });
    var dr = ["tranexamic-acid", "calcium-chloride", "calcium-gluconate", "diphenhydramine", "epinephrine"].filter(function (d) { return DB.drugs[d] && sc[d]; });
    if (k === "mt" || k === "rx") c += '<h3 class="fmh">Medications that go with it</h3><div class="drugchips">' + dr.map(function (d) { return '<button class="chip" data-drug="' + d + '">' + esc(nameOf(d)) + '</button>'; }).join("") + '</div>';
  }
  return c + '<p class="muted small" style="margin-top:12px">Education only. Transfusion follows the theater blood program, the product labels and medical direction. Not affiliated with the Armed Services Blood Program, the Joint Trauma System or the CoTCCC.</p>';
}
document.addEventListener("click", function (e) {
  var b = e.target.closest && e.target.closest("[data-blt],[data-blp],[data-blr],[data-blg],[data-blpi]"); if (!b || typeof S === "undefined") return;
  e.preventDefault(); e.stopPropagation();
  if (b.hasAttribute("data-blpi")) { S.blT = "item"; S.blP = +b.getAttribute("data-blpi"); render(); try { window.scrollTo(0, 0); } catch (x) {} return; }
  if (b.hasAttribute("data-blt")) { S.blT = b.getAttribute("data-blt"); S.blP = null; S.blR = null; render(); try { window.scrollTo(0, 0); } catch (x) {} return; }
  if (b.hasAttribute("data-blp")) { var i = +b.getAttribute("data-blp"); S.blP = S.blP === i ? null : i; }
  if (b.hasAttribute("data-blr")) { var j = +b.getAttribute("data-blr"); S.blR = S.blR === j ? null : j; }
  if (b.hasAttribute("data-blg")) S.blG = b.getAttribute("data-blg");
  render();
}, true);
