function blRegister() {
  if (!DB || !DB.drugs || blRegister.done) return; blRegister.done = true;
  BLD.forEach(function (p) {
    var s = [[p.name, p.aka || "", p.aka || "", p.cls, "Blood product", ""], [p.what, p.does, p.why], [p.mech, "", "", ""], [p.ind, p.other, p.ind, ""], [p.ci, p.ci2], [p.warn, "", p.prec], [p.dose || "", "", "", "", "", p.rate || "", "", ""],
      [p.routes, p.routes, p.routes, "", "", "", "", "", "", "", p.storage, p.comp, p.special], [p.onset, "", p.dur, "", "", "", ""], [p.se, p.se2, p.lt], ["", "", "", "", ""], ["", "", "", "", "", "", "", "", p.mon, ""], ["", "", "", "", "", ""], ["", "", "", "", "", ""],
      ["", p.know, p.check, p.after, p.stop, p.err, "", p.pearl], ["", "", "", "", ""], [p.simple, p.one, p.trick, p.fact, p.fact, "", "", ""]];
    DB.drugs[p.id] = { id: p.id, name: p.name, tags: [], s: s, blood: 1 };
    if (typeof FM_CLASS !== "undefined") FM_CLASS[p.id] = p.cls;
    if (typeof FM_EU !== "undefined" && p.eu) FM_EU[p.id] = p.eu;
  });
}
