try { blRegister(); } catch (e) {}

/* blood product dosing on Field Medic cards (owner, Oct 28 2026) */
function blIsProduct(id) { return BLD.some(function (p) { return p.id === id; }) || BLD_REAL.indexOf(id) >= 0; }
function blDoseSec(d) {
  var p = BLD.filter(function (x) { return x.id === d.id; })[0], dose = p ? p.dose : get(d, 6, 0), rate = p ? p.rate : get(d, 6, 5), mx = p ? "" : get(d, 6, 3), eud = p ? p.eud : (FM_EU[d.id] || "");
  var rows = (dose ? field("Dose", dose) : "") + (rate ? field("Rate", rate) : "") + (mx ? field("Maximum", mx) : "") + (eud ? field("What Europe does", eud) : "");
  return rows ? sec("Dose & rate", "dose", true, rows) : "";
}

/* Injuries & Illnesses: field cards for every condition in the picker (owner, Oct 28 2026: "You only have the wormhole on these.
   Also add how to treat them in the field based off FDA and other sources"). Same layout as the trauma cards: what it is,
   what goes wrong, how it is recognized, how it is treated in the field, warnings, medications, sources.
   Treatment rows note FDA-labeled uses and where a practice comes from a guideline instead (off-label). Descriptive wording; no doses.
   dis: the matching Disease Lab entry (types list + a deep-dive link). */
FM_TR_GROUPS.push("Heart and lungs", "Spine, limbs and skin", "Environmental", "Chemical and toxic", "Infection", "Metabolism and blood", "Mind and stress");
var FM_SRC_TCCC = "TCCC Guidelines, Committee on Tactical Combat Casualty Care (CoTCCC), 2026";
var FM_SRC_FDA = "FDA prescribing information (DailyMed) for the medications listed";
FM_TRAUMA.push(
  /* ---- trauma ---- */
  { id: "dic", g: 0, dis: "dic", name: "Trauma-induced coagulopathy", line: "When the blood stops clotting",
    what: "Failure of clotting after major injury, from blood loss, dilution, cold, acidosis and low calcium. Disseminated intravascular coagulation (DIC) is the late, consumptive form.",
    why: "Injured tissue and shock switch on clotting and clot breakdown at the same time. Factors and platelets are used up or diluted, and cold and acid slow the enzymes that remain, so bleeding continues from every cut surface.",
    signs: ["Oozing from wounds, IV sites and gums", "Bleeding that persists after the wound is controlled", "Shock, hypothermia and acidosis together", "Prolonged INR or abnormal viscoelastic tests where available"],
    care: [["asm", "Bleeding control and hypothermia prevention from the first minutes."], ["cmc", "TXA within 3 hours of injury (FDA-labeled for heavy menstrual bleeding and dental extraction in hemophilia; trauma use follows CRASH-2 and TCCC)."], ["cmc", "Whole blood, or plasma, red cells and platelets in balanced ratios, in TCCC order; calcium after the first product."], ["cpp", "Cryoprecipitate or fibrinogen concentrate for low fibrinogen; i-STAT ionized calcium, pH and potassium; viscoelastic testing where carried."]],
    drugs: ["tranexamic-acid", "calcium-chloride", "calcium-gluconate"],
    warn: ["Crystalloid and colloid dilute clotting factors and are not the fluid for bleeding.", "TXA started more than 3 hours after injury is linked to higher death from bleeding (CRASH-2).", "Each degree of body temperature lost slows clotting further."],
    src: [FM_SRC_TCCC, "JTS Clinical Practice Guideline: Damage Control Resuscitation, 2019", "CRASH-2 trial, Lancet 2010 and 2011", FM_SRC_FDA] },
  { id: "pneumothorax", g: 1, dis: "pneumothorax", name: "Pneumothorax and hemothorax", line: "Air or blood around the lung",
    what: "Air (pneumothorax) or blood (hemothorax) in the space between the lung and chest wall, without the pressure build-up of a tension pneumothorax.",
    why: "The lung collapses partly or fully, so less of it exchanges gas. A hemothorax also removes circulating blood; one side of the chest can hold much of the blood volume. Any pneumothorax can progress to tension.",
    signs: ["Chest pain and shortness of breath after torso trauma or blast", "Decreased breath sounds on one side", "Dull to percussion with a hemothorax; hyper-resonant with air", "Falling SpO2; ultrasound loss of lung sliding where trained"],
    care: [["cls", "Vented chest seal for any open wound; pulse oximetry; watching for tension."], ["cmc", "Oxygen; needle decompression if signs of tension develop."], ["cpp", "Tube or finger thoracostomy by trained providers for a large or worsening pneumothorax or a hemothorax; blood products for blood loss; chest tube output tracked."], ["cpp", "Flight planning: gas expands at altitude, so a drained chest or a cabin-altitude restriction is arranged before air evacuation."]],
    drugs: ["ketamine", "lidocaine", "cefazolin"],
    warn: ["A simple pneumothorax can turn into a tension pneumothorax, especially with positive-pressure ventilation or flight.", "A large early chest tube output, or steady ongoing bleeding, points to a need for surgery."],
    src: [FM_SRC_TCCC, "JTS Clinical Practice Guideline: Thoracic Trauma (Chest Injuries), 2018", "Prolonged Field Care Working Group guidance on tube thoracostomy"] },
  { id: "spinal-cord-injury", g: 4, dis: "spinal-cord-injury", name: "Spinal cord injury", line: "Protecting the cord and its blood flow",
    what: "Damage to the spinal cord from blunt force, falls, vehicle rollovers or penetrating wounds, causing weakness, numbness or paralysis below the level of injury.",
    why: "The first impact injures the cord; swelling, low blood pressure and low oxygen then extend the damage. Injuries in the neck can stop the breathing muscles and the body's control of heart rate and vessel tone (neurogenic shock).",
    signs: ["Neck or back pain after a high-energy blunt mechanism", "Weakness, numbness or tingling in the arms or legs", "Loss of bowel or bladder control, priapism", "Neurogenic shock: low blood pressure with a slow heart rate and warm skin", "Breathing with the belly only in high neck injuries"],
    care: [["asm", "Spinal motion restriction for blunt trauma with a concerning mechanism, pain or neurologic findings; TCCC does not call for it with penetrating trauma alone."], ["cmc", "Airway and oxygen; hemorrhage control and blood come first if shock is from bleeding."], ["cpp", "Neurogenic shock after bleeding is ruled out: fluid, then a vasopressor such as norepinephrine or phenylephrine; neurosurgical guidance targets a mean arterial pressure of 85 to 90 mmHg for the first week."], ["cpp", "Padding and turning to prevent pressure injuries, a urinary catheter, temperature control and early evacuation to spine surgery."]],
    drugs: ["norepinephrine", "phenylephrine", "atropine", "ketamine", "enoxaparin"],
    warn: ["High-dose methylprednisolone for acute spinal cord injury is not recommended by the AANS/CNS 2013 guidelines.", "Shock in a trauma casualty is assumed to be from bleeding until proven otherwise.", "Long-hold casualties with paralysis have a high risk of blood clots and pressure injuries."],
    src: [FM_SRC_TCCC, "JTS Clinical Practice Guideline: Cervical and Thoracolumbar Spine Injury Evaluation, Transport and Surgery, 2016", "AANS/CNS Guidelines for the Management of Acute Cervical Spine and Spinal Cord Injuries, 2013", FM_SRC_FDA] },
  { id: "burns", g: 4, dis: "burns", name: "Burns", line: "Fluid, heat loss and the airway",
    what: "Thermal, chemical, electrical or radiation injury to the skin and deeper tissue.",
    why: "Burned skin leaks fluid and protein and stops holding in heat. Large burns (over about 20% of the body surface) cause burn shock from capillary leak, and the casualty cools fast. Burned tissue swells over hours and can choke a limb, the chest or the airway.",
    signs: ["Size by the rule of nines or the casualty's palm (about 1% of body surface)", "Depth: red and painful (superficial), blistered (partial), white, leathery and numb (full thickness)", "Facial burns, soot or hoarseness (airway)", "Circumferential burns of a limb or the chest"],
    care: [["asm", "Stopping the burning process and removing smoldering clothing; TCCC notes that every TCCC intervention can be done on or through burned skin."], ["cls", "Dry, sterile or burn dressings; hypothermia prevention, which burns make more urgent."], ["cmc", "IV or IO fluid for burns over 20% of the body, with lactated Ringer's preferred, using the USAISR Rule of Ten as a starting rate and adjusting to urine output."], ["cmc", "Pain control with ketamine or fentanyl; oxygen and airway planning for inhalation injury."], ["cpp", "Hourly urine output, potassium trends and escharotomy by trained providers for circumferential burns that restrict breathing or blood flow."]],
    drugs: ["lactated-ringers", "ketamine", "fentanyl", "morphine", "ondansetron", "hydroxocobalamin"],
    warn: ["Too much fluid causes burn edema, compartment syndrome of the abdomen and limbs, and lung failure (fluid creep).", "Succinylcholine raises potassium dangerously from about 24 hours after a large burn.", "Burns rarely cause shock in the first hour; early shock points to bleeding or another injury."],
    src: [FM_SRC_TCCC, "JTS Clinical Practice Guideline: Burn Care, 2016", "USAISR Burn Center: Rule of Ten", FM_SRC_FDA] },
  { id: "fractures", g: 4, dis: "fractures", name: "Fractures and open fractures", line: "Splint, check, cover, protect from infection",
    what: "Broken bones, closed or open, from gunshot, blast, falls and vehicle crashes.",
    why: "Broken bone ends tear vessels and nerves, bleed into the surrounding tissue (a femur can hide over a liter), and in open fractures let bacteria into the bone.",
    signs: ["Pain, swelling, deformity and loss of function", "Bone visible or a wound over the fracture (open)", "Shortened, rotated leg in femur fractures", "Pulse, movement and sensation below the injury"],
    care: [["asm", "Bleeding control first."], ["cls", "Splinting in a position of function, with pulse, motor and sensation checked before and after; traction splint for a midshaft femur fracture without pelvic or ankle injury."], ["cls", "TCCC combat wound medication pack (acetaminophen and meloxicam) for pain in a casualty who can still fight; antibiotics for open fractures (cefadroxil by mouth, or ceftriaxone IV or IM when the casualty cannot swallow)."], ["cmc", "Ketamine or fentanyl for moderate to severe pain."], ["cpp", "Wound irrigation, dressing changes, compartment checks and DVT prevention during a long hold."]],
    drugs: ["acetaminophen", "meloxicam", "ketamine", "fentanyl", "cefadroxil", "ceftriaxone", "cefazolin", "enoxaparin"],
    warn: ["A splint applied too tight, or swelling under it, can cause compartment syndrome.", "TCCC lists ketorolac and other NSAIDs except meloxicam as avoided in combat casualties because of bleeding risk.", "Open fractures that go hours without antibiotics have a sharply higher infection rate."],
    src: [FM_SRC_TCCC, "JTS Clinical Practice Guideline: Orthopaedic Trauma: Extremity Fractures, 2021", "JTS Clinical Practice Guideline: Infection Prevention in Combat-Related Injuries, 2021", FM_SRC_FDA] },
  { id: "compartment-syndrome", g: 4, dis: "compartment-syndrome", name: "Compartment syndrome", line: "Swelling that strangles a limb from inside",
    what: "Rising pressure inside a closed muscle compartment, usually in the leg or forearm, after fractures, crush, burns, tourniquets or restored blood flow.",
    why: "Swelling inside the tight fascia raises pressure until it squeezes shut the small vessels. Muscle and nerve die within hours without blood flow, and dead muscle releases potassium and myoglobin.",
    signs: ["Pain out of proportion to the injury", "Pain with passive stretch of the muscles", "Tense, wood-like compartment", "Late: numbness, weakness and loss of pulse"],
    care: [["cls", "Loosening tight dressings, splints and casts; the limb kept at heart level, not raised."], ["cmc", "Frequent reassessment and documentation; pain control."], ["cpp", "Fasciotomy by a trained surgeon is the treatment; in prolonged care, evacuation priority or teleconsultation; potassium and urine color for muscle breakdown."]],
    drugs: ["ketamine", "fentanyl", "calcium-chloride", "sodium-bicarbonate"],
    warn: ["Lost pulses are a late sign; a pulse can be present while muscle is dying.", "Heavy sedation and nerve blocks can hide the pain that signals it.", "Raising the limb lowers the blood pressure reaching the compartment."],
    src: [FM_SRC_TCCC, "JTS Clinical Practice Guideline: Compartment Syndrome and Fasciotomy, 2016", "JTS Clinical Practice Guideline: Prolonged Casualty Care Guidelines, 2021"] },
  { id: "rhabdomyolysis", g: 4, dis: "rhabdomyolysis", name: "Rhabdomyolysis", line: "Muscle breakdown that can stop the kidneys",
    what: "Breakdown of skeletal muscle from crush, blast, burns, heat stroke or extreme exertion such as ruck marches and training.",
    why: "Dying muscle releases potassium (heart rhythm danger), acid, and myoglobin, which clogs and poisons the kidney tubules when urine flow is low.",
    signs: ["Muscle pain, swelling and weakness", "Dark, tea- or cola-colored urine", "Low urine output", "Recent crush, heat injury or extreme exercise"],
    care: [["cls", "Stopping exertion; cooling if heat is involved; oral fluids if able."], ["cmc", "IV or IO crystalloid aimed at a high urine output."], ["cpp", "Urine output tracking; i-STAT potassium and creatinine; treatment of high potassium with calcium, insulin with dextrose and albuterol."]],
    drugs: ["lactated-ringers", "plasma-lyte", "calcium-chloride", "regular-insulin", "dextrose", "albuterol", "sodium-bicarbonate"],
    warn: ["NSAIDs add kidney injury and are avoided.", "Bicarbonate and mannitol have not been shown to prevent kidney failure in rhabdomyolysis and are not routine.", "Exertional rhabdomyolysis often affects several trainees in the same event."],
    src: ["JTS Clinical Practice Guideline: Hyperkalemia and Dialysis in the Deployed Setting, 2017", "Uniformed Services University CHAMP: Clinical Practice Guideline for Exertional Rhabdomyolysis, 2020", FM_SRC_FDA] },
  /* ---- medical: heart and lungs ---- */
  { id: "cardiac-arrest", g: 3, dis: "cardiac-arrest", name: "Cardiac arrest", line: "Medical arrest versus traumatic arrest",
    what: "The heart stops pumping effective blood. In the field it splits into medical arrest (rhythm problems, heat, drowning, electrocution) and traumatic arrest (bleeding, tension pneumothorax, airway).",
    why: "Without flow, the brain is injured within minutes. In medical arrest a shockable rhythm can often be reversed with early CPR and defibrillation; in traumatic arrest the cause is usually empty or blocked circulation that CPR alone cannot fix.",
    signs: ["Unresponsive, not breathing normally, no pulse", "Rhythm on a monitor: VF or pulseless VT (shockable), asystole or PEA (non-shockable)", "Mechanism: blast or gunshot points to traumatic arrest"],
    care: [["cls", "Medical arrest: high-quality CPR and early defibrillation for VF or pulseless VT (AHA)."], ["cpp", "ACLS: epinephrine (FDA-labeled to increase mean arterial pressure in shock; arrest use follows AHA), and amiodarone or lidocaine for refractory VF or pulseless VT."], ["cmc", "Traumatic arrest (TCCC): bleeding control, bilateral needle decompression for torso or blast trauma, airway, and blood products."], ["cpp", "Reversible causes reviewed (the Hs and Ts), including hyperkalemia, hypothermia, low blood volume, tension pneumothorax and tamponade."]],
    drugs: ["epinephrine", "amiodarone", "lidocaine", "calcium-chloride", "sodium-bicarbonate", "magnesium-sulfate"],
    warn: ["TCCC states that CPR on the battlefield for blast or penetrating trauma without signs of life is not likely to succeed and can cost other casualties care.", "Hypothermic casualties can survive long arrests; rewarming is part of resuscitation.", "Magnesium is for torsades de pointes, not every arrest."],
    src: [FM_SRC_TCCC, "American Heart Association Guidelines for CPR and Emergency Cardiovascular Care", FM_SRC_FDA] },
  { id: "anaphylaxis", g: 3, dis: "anaphylaxis", name: "Anaphylaxis", line: "Allergy that closes the airway and drops the pressure",
    what: "A sudden, severe allergic reaction to stings, food, drugs (including antibiotics) or blood products.",
    why: "Mast cells release histamine and other mediators throughout the body. Blood vessels open and leak (shock), airways narrow and swell, and the gut cramps.",
    signs: ["Hives, flushing or swelling of the lips, tongue or throat", "Wheezing, stridor or shortness of breath", "Low blood pressure, fainting", "Vomiting or abdominal cramps after an exposure"],
    care: [["cls", "Intramuscular epinephrine in the outer thigh, FDA-labeled as the first treatment for anaphylaxis, repeated if symptoms persist."], ["cmc", "Oxygen; IV or IO fluid for low blood pressure; albuterol for wheezing."], ["cpp", "Antihistamines (diphenhydramine and famotidine) and a steroid (methylprednisolone) as add-ons; an epinephrine infusion for shock that does not respond."], ["cpp", "Observation for a second (biphasic) reaction, which can come hours later."]],
    drugs: ["epinephrine", "diphenhydramine", "famotidine", "methylprednisolone", "albuterol", "racemic-epinephrine", "lactated-ringers"],
    warn: ["Antihistamines and steroids do not treat airway swelling or shock; epinephrine does.", "A transfusion reaction with hives and wheezing means stopping the transfusion.", "Casualties on beta-blockers can respond poorly to epinephrine."],
    src: ["World Allergy Organization Anaphylaxis Guidance, 2020", "Joint Task Force on Practice Parameters: Anaphylaxis 2023 Practice Parameter Update", FM_SRC_FDA] },
  { id: "ards", g: 3, dis: "ards", name: "ARDS", line: "Lungs that fill with leaked fluid",
    what: "Acute respiratory distress syndrome: widespread lung inflammation and leakage after blast, burns, smoke, sepsis, massive transfusion or aspiration.",
    why: "Inflamed capillaries leak protein-rich fluid into the air sacs, which collapse and stop exchanging oxygen. The lungs become stiff, and high ventilator pressures can injure them further.",
    signs: ["Low SpO2 despite oxygen", "Fast breathing and work of breathing, hours to days after the injury", "Rising ventilator pressures", "Bilateral changes on ultrasound or X-ray"],
    care: [["cpp", "Oxygen, then non-invasive or invasive ventilation by trained providers."], ["cpp", "Lung-protective ventilation: low tidal volume based on predicted body weight, PEEP, and a plateau pressure kept under about 30 cmH2O (ARDSNet)."], ["cpp", "Conservative fluids once shock is resolved; treatment of the cause (sepsis, infection); prone positioning when staff and setting allow."], ["cpp", "Sedation and analgesia for ventilator synchrony (ketamine, fentanyl, propofol or dexmedetomidine)."]],
    drugs: ["ketamine", "fentanyl", "propofol", "dexmedetomidine", "rocuronium"],
    warn: ["Large tidal volumes and high pressures worsen the lung injury.", "Air evacuation at altitude lowers available oxygen; cabin altitude and oxygen supply are planned in advance."],
    src: ["ARDS Network: Lower Tidal Volume trial, N Engl J Med 2000", "JTS Clinical Practice Guideline: Acute Respiratory Failure, 2017", "JTS Clinical Practice Guideline: Prolonged Casualty Care Guidelines, 2021", FM_SRC_FDA] },
  { id: "pulmonary-embolism", g: 3, dis: "pulmonary-embolism", name: "Pulmonary embolism", line: "A clot that blocks the lungs",
    what: "A blood clot, usually from the leg veins, that travels to and blocks the lung arteries.",
    why: "Blocked arteries stop part of the lung from receiving blood, so oxygen falls. A large clot strains the right side of the heart until it fails, causing shock and arrest.",
    signs: ["Sudden shortness of breath or chest pain, often days after injury", "Fast heart rate, low SpO2", "Swollen leg (DVT)", "Collapse or shock with a large clot; right-heart strain on ultrasound"],
    care: [["cpp", "Oxygen and monitoring; urgent evacuation."], ["cpp", "Anticoagulation with enoxaparin, FDA-labeled for treatment of DVT with or without PE, when bleeding risk allows."], ["cpp", "Massive PE with shock: vasopressor support (norepinephrine) and thrombolysis (alteplase is FDA-labeled for massive PE) where available."]],
    drugs: ["enoxaparin", "norepinephrine", "epinephrine"],
    warn: ["Anticoagulation in a trauma casualty with uncontrolled bleeding or a fresh brain injury can be fatal; risk is weighed with a physician.", "Large fluid volumes can worsen a failing right heart."],
    src: ["American College of Chest Physicians (CHEST) Guideline: Antithrombotic Therapy for VTE Disease, 2021", "European Society of Cardiology Guidelines for Acute Pulmonary Embolism, 2019", FM_SRC_FDA] },
  { id: "deep-vein-thrombosis", g: 3, dis: "deep-vein-thrombosis", name: "Deep vein thrombosis", line: "The clot risk of a long hold",
    what: "A blood clot in a deep vein, usually the leg or pelvis, common after trauma, immobility and long evacuations.",
    why: "Injury makes blood more likely to clot, immobility slows flow, and damaged vessel walls give clots a place to start (Virchow's triad). Pieces can break off and become a pulmonary embolism.",
    signs: ["Swelling, warmth and pain in one leg", "Often no signs at all in trauma casualties", "Clot seen on compression ultrasound by trained providers"],
    care: [["cpp", "Prevention: movement when possible, compression devices, and enoxaparin (FDA-labeled for DVT prevention) once bleeding is controlled, per JTS guidance."], ["cpp", "Treatment of a confirmed clot with anticoagulation when bleeding risk allows, and evacuation."]],
    drugs: ["enoxaparin"],
    warn: ["Trauma casualties have one of the highest clot risks in medicine.", "Enoxaparin is held with active bleeding, an untreated brain bleed or spinal procedures soon planned."],
    src: ["JTS Clinical Practice Guideline: Prevention of Deep Venous Thrombosis, 2016", "CHEST Guideline: Antithrombotic Therapy for VTE Disease, 2021", FM_SRC_FDA] },
  /* ---- environmental ---- */
  { id: "heat-stroke", g: 5, dis: "heat-stroke", name: "Heat stroke", line: "Cool first, transport second",
    what: "A core temperature usually above 40 C (104 F) with brain dysfunction (confusion, collapse, seizures), most often from exertion in heat.",
    why: "When heat production outruns heat loss, proteins and cell membranes break down. The gut leaks bacteria and toxins, clotting fails, and muscle, liver and kidneys are damaged. The time spent above 40 C drives the damage.",
    signs: ["Confusion, odd behavior or collapse during exertion or heat", "Hot skin, sweating or dry", "Rectal temperature above 40 C (104 F); oral and ear readings miss it", "Seizures, vomiting, fast heart rate"],
    care: [["asm", "Cooling starts on scene, before transport: cold-water immersion is the gold standard; ice sheets or ice-water-soaked towels rotated over the body (Army TB MED 507) when immersion is not possible."], ["cls", "Cooling continues until rectal temperature is about 39 C (102 F), then stops to avoid overshooting."], ["cmc", "IV or IO fluid; glucose check; benzodiazepines for seizures or shivering that blocks cooling."], ["cpp", "i-STAT potassium, glucose and kidney values; watching for rhabdomyolysis, bleeding and liver injury; evacuation once cooled."]],
    drugs: ["lactated-ringers", "plasma-lyte", "midazolam", "lorazepam", "diazepam", "dextrose"],
    warn: ["Acetaminophen and other fever drugs do not work for heat stroke and are avoided.", "Survival is close to 100% when cooling starts within 30 minutes (ACSM).", "Exertional heat stroke can occur in mild weather during hard training."],
    src: ["Army TB MED 507: Heat Stress Control and Heat Casualty Management, 2022", "American College of Sports Medicine Expert Consensus Statement on Exertional Heat Illness, 2023", "Wilderness Medical Society Clinical Practice Guidelines for Heat Illness, 2019 update"] },
  { id: "hypothermia", g: 5, dis: "hypothermia", name: "Hypothermia", line: "Cold that kills the injured and the healthy",
    what: "A core temperature below 35 C (95 F), from cold, wet or windy exposure, immersion, or blood loss and shock in trauma.",
    why: "Cold slows every enzyme. Clotting fails (part of the lethal diamond in trauma), the heart becomes irritable and prone to VF, and the brain slows until the casualty stops shivering and loses consciousness.",
    signs: ["Shivering, clumsiness and confusion (mild)", "Shivering stops, drowsiness (moderate)", "Unconscious, slow or undetectable pulse and breathing (severe)", "Any trauma casualty, even in warm climates"],
    care: [["asm", "Removal of wet clothing, insulation from the ground, wind protection; the Hypothermia Prevention and Management Kit (HPMK) for trauma casualties (TCCC)."], ["cls", "Active warming to the chest, back and armpits; warm, sweet drinks only for an alert casualty who can swallow."], ["cmc", "Warmed IV or IO fluids and blood; gentle, horizontal handling."], ["cpp", "Monitoring for arrhythmias; in arrest, CPR continues and rewarming is pursued, since cold casualties can recover after long resuscitation."]],
    drugs: ["dextrose", "lactated-ringers", "epinephrine"],
    warn: ["Rough handling of a severely cold casualty can trigger VF.", "A casualty who looks dead may be recoverable; WMS guidance supports CPR during transport and rewarming.", "Rubbing frozen or cold skin causes more injury."],
    src: [FM_SRC_TCCC, "Wilderness Medical Society Clinical Practice Guidelines for the Out-of-Hospital Evaluation and Treatment of Accidental Hypothermia, 2019 update", "JTS Clinical Practice Guideline: Hypothermia Prevention, Monitoring and Management, 2023"] },
  { id: "drowning", g: 5, dis: "drowning", name: "Drowning", line: "Oxygen first",
    what: "Breathing difficulty from submersion or immersion in water, from water operations, river crossings, vehicle rollovers into water and dive accidents.",
    why: "Water in the airway and lungs washes out surfactant and floods the air sacs, so oxygen falls fast. Low oxygen, not water volume, causes the cardiac arrest.",
    signs: ["Coughing, foam at the mouth, shortness of breath after water rescue", "Low SpO2, crackles", "Confusion or unconsciousness", "Arrest from low oxygen"],
    care: [["asm", "Rescue without becoming a second casualty; casualty removed horizontally when possible."], ["cls", "Rescue breaths and ventilation first, because the arrest is from low oxygen; CPR in A-B-C order for drowning (WMS, AHA)."], ["cmc", "Oxygen; spine precautions only when a diving or high-impact injury is suspected."], ["cpp", "PEEP or CPAP for low oxygen; observation for delayed worsening; warming."]],
    drugs: ["epinephrine"],
    warn: ["Abdominal thrusts to expel water delay ventilation and cause vomiting; they are not recommended.", "A casualty who seems fine can worsen over the next hours; WMS guidance supports observation for about 4 to 6 hours.", "Cold water drownings can survive long submersions."],
    src: ["Wilderness Medical Society Clinical Practice Guidelines for the Treatment and Prevention of Drowning, 2019 update", "American Heart Association Guidelines for CPR and Emergency Cardiovascular Care: drowning"] },
  { id: "altitude-sickness", g: 5, dis: "altitude-sickness", name: "Altitude illness", line: "AMS, HACE and HAPE",
    what: "Illness from ascending to high altitude (usually above 2,500 m or 8,000 ft) faster than the body adapts: acute mountain sickness (AMS), high-altitude cerebral edema (HACE) and high-altitude pulmonary edema (HAPE).",
    why: "Thin air lowers blood oxygen. The brain's vessels leak and it swells (AMS, HACE), and the lung's vessels clamp down unevenly and leak fluid (HAPE).",
    signs: ["AMS: headache with nausea, fatigue, dizziness or poor sleep", "HACE: confusion, clumsy walking (ataxia), drowsiness", "HAPE: breathlessness at rest, cough, falling exercise ability, low SpO2 compared with peers"],
    care: [["asm", "Stopping ascent; descent for any HACE or HAPE, or worsening AMS; descent of even 300 to 1,000 m helps."], ["cmc", "Oxygen; a portable hyperbaric bag when descent is not possible."], ["cpp", "Acetazolamide, FDA-labeled for acute mountain sickness, for prevention and treatment; dexamethasone for HACE (off-label, WMS); nifedipine for HAPE (off-label, WMS)."]],
    drugs: [],
    warn: ["Medications buy time; descent is the definitive treatment for HACE and HAPE.", "Dexamethasone treats symptoms but does not speed adaptation; symptoms can return when it stops.", "Rapid helicopter insertion to altitude skips the gradual ascent that prevents illness."],
    src: ["Wilderness Medical Society Clinical Practice Guidelines for the Prevention and Treatment of Acute Altitude Illness, 2024 update", "U.S. Army Research Institute of Environmental Medicine (USARIEM) Altitude Acclimatization Guide", "FDA prescribing information: acetazolamide"] },
  { id: "decompression-sickness", g: 5, dis: "decompression-sickness", name: "Decompression illness", line: "Bubbles from diving or flight",
    what: "Decompression sickness (gas bubbles forming in tissues on ascent) and arterial gas embolism (bubbles entering arteries from burst lung tissue), from diving, high-altitude flight or hypobaric chambers.",
    why: "Nitrogen dissolved at depth comes out of solution on ascent. Bubbles block vessels, inflame tissue and injure the spinal cord, brain, joints and lungs. A lung over-pressure injury can send air straight to the brain.",
    signs: ["Joint pain (the bends), rash, itching", "Numbness, weakness, paralysis or bladder problems (spinal)", "Confusion, stroke-like signs or collapse within minutes of surfacing (gas embolism)", "Chest pain, cough and shortness of breath (the chokes)"],
    care: [["asm", "100% oxygen by tight-fitting mask, continued until recompression."], ["cls", "Lying flat; oral or IV fluids; neurologic exam recorded."], ["cpp", "Recompression in a chamber per U.S. Navy Treatment Table 6 for serious symptoms, coordinated through the Navy Experimental Diving Unit or a dive medical officer."], ["cpp", "Air evacuation at the lowest safe altitude or with a cabin pressurized to sea level."]],
    drugs: ["lactated-ringers", "plasma-lyte"],
    warn: ["Symptoms that clear with oxygen still need recompression evaluation; they can return.", "Flying soon after diving is a well-known trigger.", "The Dive tables tab in Field Medic has the limits that prevent it."],
    src: ["U.S. Navy Diving Manual, Revision 7, Volume 5: Diving Medicine and Recompression Chamber Operations", "Undersea and Hyperbaric Medical Society (UHMS) Guidelines for Adjunctive Treatment of Decompression Illness"] },
  { id: "snakebite", g: 5, dis: "snakebite", name: "Snakebite", line: "Calm, still, and moving toward antivenom",
    what: "Envenomation from snakes such as vipers (rattlesnakes, saw-scaled vipers) or elapids (cobras, kraits, mambas, coral snakes), depending on the region.",
    why: "Viper venom destroys tissue and blocks clotting, causing swelling, bleeding and shock. Elapid venom mostly blocks nerve-to-muscle signaling, causing drooping eyelids, weakness and breathing failure, sometimes with little local pain.",
    signs: ["Fang marks, pain and spreading swelling (vipers)", "Bleeding from gums, wounds or IV sites; blood not clotting in a tube", "Drooping eyelids, double vision, slurred speech, weakness (elapids)", "Nausea, low blood pressure, collapse"],
    care: [["asm", "Moving away from the snake; keeping the casualty calm and the limb still and at heart level; rings and watches removed before swelling."], ["cls", "Marking the edge of swelling with the time; pressure immobilization bandage for elapid bites where that is the local guidance."], ["cpp", "Evacuation to antivenom: CroFab and Anavip are FDA-approved for North American pit vipers; deployed forces use theater antivenom sources coordinated through medical command."], ["cpp", "Airway and ventilation for paralysis; treatment of anaphylaxis to antivenom with epinephrine."]],
    drugs: ["epinephrine", "diphenhydramine", "fentanyl", "acetaminophen"],
    warn: ["Tourniquets, cutting, suction, ice and electric shock are not recommended (WHO, WMS).", "NSAIDs are avoided because venom can already impair clotting.", "Some elapid bites cause little pain but lead to paralysis hours later."],
    src: ["WHO Guidelines for the Management of Snakebites, 2nd edition, 2016", "Wilderness Medical Society Clinical Practice Guidelines on the Management of Snakebites, 2021", "FDA prescribing information: CroFab, Anavip"] },
  { id: "carbon-monoxide", g: 5, dis: "carbon-monoxide", name: "Carbon monoxide poisoning", line: "The heater in the tent",
    what: "Poisoning from carbon monoxide in fires, generators, vehicle exhaust, heaters in tents or shelters, and enclosed-space explosions.",
    why: "Carbon monoxide binds hemoglobin far more tightly than oxygen and stays there, so blood carries less oxygen and releases it poorly. It also poisons the cell's energy machinery, injuring the brain and heart.",
    signs: ["Headache, dizziness, nausea in several people in one space", "Confusion, chest pain, collapse or seizures", "Normal SpO2 on a standard pulse oximeter despite poisoning"],
    care: [["asm", "Removal from the source and fresh air for everyone exposed."], ["cls", "High-flow 100% oxygen by non-rebreather mask, which shortens CO's half-life."], ["cpp", "Hyperbaric oxygen for severe poisoning (unconsciousness, neurologic signs, pregnancy, cardiac injury) per UHMS, where reachable; cyanide is considered with smoke from fires."]],
    drugs: ["hydroxocobalamin"],
    warn: ["Standard pulse oximeters read carbon monoxide as oxygen; a CO-oximeter is needed.", "Delayed brain problems (memory, mood) can appear weeks later."],
    src: ["Undersea and Hyperbaric Medical Society (UHMS) Indications: Carbon Monoxide Poisoning", "American College of Emergency Physicians Clinical Policy: Carbon Monoxide Poisoning, 2017"] },
  /* ---- chemical and toxic ---- */
  { id: "organophosphate-poisoning", g: 6, dis: "organophosphate-poisoning", name: "Nerve agent and organophosphate poisoning", line: "Too much acetylcholine everywhere",
    what: "Poisoning by nerve agents (sarin, VX, Novichok) or organophosphate and carbamate pesticides, by vapor, liquid on skin or swallowing.",
    why: "These agents block acetylcholinesterase, so acetylcholine builds up at every synapse. Glands pour out secretions, airways clamp down, muscles twitch then fail, and the brain seizes.",
    signs: ["Pinpoint pupils, runny nose, drooling, sweating", "Wheezing and heavy airway secretions", "Muscle twitching, weakness, paralysis", "Vomiting, diarrhea, urination (SLUDGE)", "Seizures and collapse"],
    care: [["asm", "Protective mask and gear (MOPP) for rescuers; removal from the area; decontamination."], ["cls", "Autoinjectors: atropine with pralidoxime (ATNAA or DuoDote, FDA-approved for nerve agent and organophosphate poisoning), repeated by symptom severity per military protocol."], ["cls", "Midazolam autoinjector, FDA-approved for status epilepticus, for seizures (replaced diazepam in the military kit)."], ["cpp", "More atropine until secretions dry and breathing eases; airway and ventilation; glycopyrrolate as an add-on for secretions."]],
    drugs: ["atropine", "midazolam", "diazepam", "lorazepam", "glycopyrrolate"],
    warn: ["The endpoint of atropine is dry airway secretions and easier breathing, not pupil size or heart rate.", "Succinylcholine has a prolonged effect after these agents and is avoided.", "Contaminated clothing and skin can poison caregivers."],
    src: ["U.S. Army Medical Research Institute of Chemical Defense (USAMRICD) Medical Management of Chemical Casualties Handbook", "CHEMM (HHS Chemical Hazards Emergency Medical Management): Nerve Agents", "FDA prescribing information: ATNAA, DuoDote, Seizalam (midazolam)"] },
  { id: "cyanide-poisoning", g: 6, dis: "cyanide-poisoning", name: "Cyanide poisoning", line: "Oxygen in the blood that cells cannot use",
    what: "Poisoning from cyanide in smoke from burning plastics and fabrics, industrial accidents or chemical attack.",
    why: "Cyanide blocks the last step of cellular respiration, so cells cannot use oxygen even when blood is full of it. Lactic acid builds, and the brain and heart fail within minutes.",
    signs: ["Smoke exposure in an enclosed space with confusion or collapse", "Fast breathing, then slow breathing", "Seizures, low blood pressure, arrest", "Very high lactate on i-STAT where available"],
    care: [["asm", "Removal from the source and decontamination."], ["cmc", "High-flow oxygen and airway support."], ["cpp", "Hydroxocobalamin (Cyanokit), FDA-approved for known or suspected cyanide poisoning; sodium nitrite with sodium thiosulfate (Nithiodote) is the older FDA-approved alternative."]],
    drugs: ["hydroxocobalamin", "amyl-nitrite", "sodium-bicarbonate"],
    warn: ["Hydroxocobalamin turns skin and urine red and interferes with some lab tests and CO-oximetry for days.", "Nitrites lower oxygen carrying and are risky when carbon monoxide is also present (fires); hydroxocobalamin is preferred for smoke."],
    src: ["CHEMM (HHS): Cyanide", "USAMRICD Medical Management of Chemical Casualties Handbook", "FDA prescribing information: Cyanokit, Nithiodote"] },
  { id: "opioid-overdose", g: 6, dis: "opioid-overdose", name: "Opioid overdose", line: "Breathing stops before the heart",
    what: "Too much opioid effect, from fentanyl, morphine or other opioids, including stacked doses of pain medication in casualties.",
    why: "Opioids blunt the brain's breathing response to carbon dioxide, so breathing slows and stops, oxygen falls and the heart arrests.",
    signs: ["Slow or stopped breathing", "Pinpoint pupils", "Unresponsive or very drowsy", "Low SpO2 and rising EtCO2"],
    care: [["cls", "Airway positioning and bag-valve-mask ventilation, which treat the low oxygen directly."], ["cls", "Naloxone, FDA-approved for opioid overdose, by nasal, IM or IV route; TCCC carries it wherever opioids are given."], ["cmc", "Naloxone titrated to adequate breathing rather than full wakefulness."], ["cpp", "Observation for re-sedation, since naloxone can wear off before the opioid."]],
    drugs: ["naloxone", "fentanyl", "morphine"],
    warn: ["Full reversal in a casualty in pain brings back severe pain and agitation; TCCC aims for adequate breathing.", "Long-acting or large opioid doses can outlast naloxone."],
    src: [FM_SRC_TCCC, "American Heart Association: Opioid-Associated Emergencies, 2023 focused update", "FDA prescribing information: naloxone"] },
  { id: "benzodiazepine-overdose", g: 6, dis: "benzodiazepine-overdose", name: "Sedative overdose", line: "Benzodiazepines, alone or with opioids",
    what: "Too much benzodiazepine effect (midazolam, lorazepam, diazepam), often combined with opioids, alcohol or other sedatives.",
    why: "Benzodiazepines strengthen the brain's main calming signal (GABA). Alone they cause deep sedation; with opioids or alcohol, breathing stops.",
    signs: ["Deep drowsiness or unresponsiveness", "Slurred speech, poor coordination", "Slow breathing, especially with opioids", "Normal-size pupils unless opioids are also involved"],
    care: [["cls", "Airway positioning and ventilation as needed."], ["cmc", "Naloxone when opioids may also be involved."], ["cpp", "Supportive care until it wears off; flumazenil (FDA-labeled to reverse benzodiazepine sedation) in selected cases such as procedural over-sedation."]],
    drugs: ["flumazenil", "naloxone", "midazolam"],
    warn: ["Flumazenil carries an FDA boxed warning for seizures, especially in long-term benzodiazepine users and mixed overdoses.", "Flumazenil wears off sooner than many benzodiazepines, so sedation can return."],
    src: ["American College of Medical Toxicology position statements", "FDA prescribing information: flumazenil"] },
  /* ---- infection ---- */
  { id: "sepsis", g: 7, dis: "sepsis", name: "Sepsis and septic shock", line: "Infection that turns on the whole body",
    what: "Organ failure caused by the body's response to infection, from wounds, pneumonia, the urinary tract or the gut. In prolonged care it is a leading cause of late death.",
    why: "The immune response to infection floods the body with inflammatory signals. Vessels leak and open (low blood pressure), clotting goes awry, and organs get too little oxygen.",
    signs: ["Fever or low temperature, fast heart rate, fast breathing", "Confusion", "Low blood pressure, cool or mottled skin, low urine output", "Red, swollen, foul-smelling wound; rising lactate"],
    care: [["cls", "TCCC antibiotics for every open combat wound to prevent infection."], ["cpp", "Antibiotics as soon as possible, within an hour for septic shock (Surviving Sepsis Campaign): ertapenem, ceftriaxone with metronidazole, or moxifloxacin in the field kit."], ["cpp", "Crystalloid fluid bolus; norepinephrine as the first-choice vasopressor for a mean arterial pressure of 65 mmHg or more."], ["cpp", "Source control: opening and cleaning infected wounds; tracking lactate, urine output and mental status; evacuation."]],
    drugs: ["ertapenem", "ceftriaxone", "metronidazole", "moxifloxacin", "cefazolin", "lactated-ringers", "plasma-lyte", "norepinephrine", "vasopressin", "epinephrine"],
    warn: ["Each hour of delay in antibiotics for septic shock is linked to higher mortality.", "Large fluid volumes can cause lung edema; repeat checks guide more fluid.", "Wound infections in a long hold often need debridement, not just antibiotics."],
    src: ["Surviving Sepsis Campaign International Guidelines, 2021", "JTS Clinical Practice Guideline: Sepsis Management in Prolonged Field Care, 2020", FM_SRC_TCCC, FM_SRC_FDA] },
  { id: "cellulitis", g: 7, dis: "cellulitis", name: "Skin and wound infection", line: "Cellulitis, abscess and the one to fear",
    what: "Infection of the skin and soft tissue: cellulitis, abscesses, infected wounds, and rarely necrotizing fasciitis.",
    why: "Bacteria (mostly staph and strep) enter through breaks in the skin, blisters and insect bites, then spread through tissue. Necrotizing infections spread along the fascia and kill tissue fast.",
    signs: ["Spreading redness, warmth, swelling and pain", "A fluctuant, pus-filled lump (abscess)", "Red streaks up the limb", "Red flags: pain out of proportion, skin crackling (gas), dusky or blistered skin, rapid spread, shock"],
    care: [["cls", "Marking the border of redness with the time to track spread."], ["cpp", "Incision and drainage for an abscess by trained providers; antibiotics per IDSA guidance, such as cephalexin or cefadroxil, with MRSA coverage for purulent infections."], ["cpp", "IV antibiotics (cefazolin, ceftriaxone) for spreading or systemic infection; immediate evacuation to surgery for suspected necrotizing fasciitis."]],
    drugs: ["cephalexin", "cefadroxil", "cefazolin", "ceftriaxone", "metronidazole", "acetaminophen"],
    warn: ["Necrotizing fasciitis is a surgical emergency; antibiotics alone do not stop it.", "Blisters from rucks and boots are a common entry point in training."],
    src: ["IDSA Practice Guidelines for the Diagnosis and Management of Skin and Soft Tissue Infections, 2014", "JTS Clinical Practice Guideline: Infection Prevention in Combat-Related Injuries, 2021", FM_SRC_FDA] },
  { id: "osteomyelitis", g: 7, dis: "osteomyelitis", name: "Bone infection", line: "The long tail of open fractures",
    what: "Infection of bone, mostly after open fractures and blast wounds, including resistant organisms picked up in theater.",
    why: "Bacteria reach bone through the wound and live in dead bone fragments and on hardware, where antibiotics penetrate poorly.",
    signs: ["Increasing pain, swelling and redness at a fracture", "Pus or a draining tract", "Fever, or no fever at all", "Wound that fails to heal"],
    care: [["cls", "Prevention: early TCCC antibiotics for open fractures, wound coverage and splinting."], ["cpp", "Irrigation and dressing changes; IV antibiotics such as cefazolin or ceftriaxone while awaiting surgery."], ["cpp", "Surgical debridement and weeks of targeted antibiotics after evacuation."]],
    drugs: ["cefazolin", "ceftriaxone", "cefadroxil", "ertapenem"],
    warn: ["Multidrug-resistant bacteria are common in combat wound infections.", "Antibiotics without removal of dead bone rarely cure it."],
    src: ["JTS Clinical Practice Guideline: Infection Prevention in Combat-Related Injuries, 2021", FM_SRC_FDA] },
  { id: "tetanus", g: 7, dis: "tetanus", name: "Tetanus", line: "Toxin-driven muscle spasm",
    what: "Muscle spasm caused by toxin from Clostridium tetani, which lives in soil and enters through dirty wounds, burns and punctures.",
    why: "The toxin travels up nerves and blocks the brake signals on motor neurons, so muscles lock and spasm. The breathing muscles and the autonomic nervous system are affected.",
    signs: ["Jaw stiffness (lockjaw), facial grimace", "Stiff neck, back arching", "Painful spasms set off by noise or touch", "Swings in heart rate and blood pressure"],
    care: [["cls", "Prevention: wound cleaning and tetanus vaccine status checked; Tdap and tetanus immune globulin for unvaccinated casualties with dirty wounds (CDC)."], ["cpp", "Benzodiazepines for spasms (midazolam, diazepam), magnesium as an add-on, and metronidazole (WHO preferred) to kill the bacteria."], ["cpp", "Tetanus immune globulin; a dark, quiet space; airway and ventilator support; evacuation."]],
    drugs: ["midazolam", "diazepam", "lorazepam", "magnesium-sulfate", "metronidazole"],
    warn: ["Spasms can stop breathing; an airway plan comes early.", "Having had tetanus does not create immunity; vaccination is still needed."],
    src: ["CDC: Tetanus, Clinical Overview and Wound Management", "WHO: Current recommendations for treatment of tetanus during humanitarian emergencies", FM_SRC_FDA] },
  { id: "malaria", g: 7, dis: "malaria", name: "Malaria", line: "Fever after a mosquito region",
    what: "A parasite infection spread by mosquitoes in Africa, Asia, the Pacific and Latin America. Plasmodium falciparum causes most deaths.",
    why: "Parasites multiply in the liver, then burst red blood cells in waves. Falciparum makes infected cells stick in small vessels of the brain, kidneys and lungs.",
    signs: ["Fever, chills and sweats, headache, body aches", "Any fever during or after deployment to a malaria area", "Severe: confusion or seizures, breathing trouble, dark urine, jaundice, bleeding, shock", "Positive rapid diagnostic test (RDT) or blood smear"],
    care: [["cls", "Prevention: prophylaxis medication, insect repellent, treated uniforms and bed nets."], ["cpp", "Rapid diagnostic test; uncomplicated falciparum treated with artemether-lumefantrine (Coartem, FDA-approved)."], ["cpp", "Severe malaria: IV artesunate (FDA-approved in 2020 for severe malaria), glucose checks, fluids with caution and urgent evacuation."], ["cpp", "Primaquine or tafenoquine (FDA-approved) after return to clear dormant P. vivax and P. ovale, after G6PD testing."]],
    drugs: ["dextrose", "acetaminophen", "ondansetron"],
    warn: ["Malaria can appear weeks to months after leaving the region.", "Primaquine and tafenoquine can destroy red cells in people with G6PD deficiency.", "Severe malaria causes low blood sugar."],
    src: ["CDC Treatment of Malaria: Guidelines for Clinicians (United States)", "WHO Guidelines for Malaria", "Armed Forces Health Surveillance Division (AFHSD) and DoD Force Health Protection guidance", "FDA prescribing information: artesunate, Coartem, primaquine, tafenoquine"] },
  { id: "rabies", g: 7, dis: "rabies", name: "Rabies exposure", line: "Washing and post-exposure shots",
    what: "A viral infection spread through bites or scratches from infected animals, mostly dogs in deployed settings, and bats.",
    why: "The virus travels slowly up nerves to the brain, so there is a window for prevention. Once symptoms begin, it is almost universally fatal.",
    signs: ["Any bite or scratch from a dog, cat, monkey, bat or wild animal, especially overseas", "Bat contact where a bite cannot be ruled out", "Late: fever, tingling at the bite, agitation, fear of water, paralysis"],
    care: [["asm", "Immediate washing of the wound with soap and water for about 15 minutes (CDC, WHO)."], ["cls", "Reporting every animal bite to the chain of command and preventive medicine."], ["cpp", "Post-exposure prophylaxis: rabies immune globulin into and around the wound and a series of rabies vaccine shots, per CDC."], ["cpp", "Tetanus status checked; antibiotics for high-risk bites such as hand bites."]],
    drugs: ["cefadroxil", "ceftriaxone"],
    warn: ["Feeding or handling local animals on deployment is a leading cause of exposures.", "Prophylaxis works when given before symptoms; once symptoms begin it does not."],
    src: ["CDC: Rabies Post-Exposure Prophylaxis", "WHO Expert Consultation on Rabies, 2018", "Armed Forces Health Surveillance Division: animal bites in service members"] },
  { id: "meningitis", g: 7, dis: "meningitis", name: "Meningitis", line: "Fever, headache, stiff neck, rash",
    what: "Infection of the membranes around the brain and spinal cord. Meningococcal meningitis spreads in barracks and close quarters.",
    why: "Bacteria in the spinal fluid trigger brain swelling and inflammation. Meningococcus can also spread through the blood and cause shock and a purple rash within hours.",
    signs: ["Fever, severe headache, stiff neck", "Confusion, light sensitivity, vomiting", "A purple rash that does not fade when pressed", "Shock in meningococcemia"],
    care: [["cpp", "Ceftriaxone as soon as it is suspected, without waiting for testing (IDSA), plus vancomycin for resistant pneumococcus where available."], ["cpp", "Dexamethasone given just before or with the first antibiotic for suspected pneumococcal meningitis (IDSA)."], ["cpp", "Droplet precautions; treatment of shock; prophylaxis for close contacts (ciprofloxacin, rifampin or ceftriaxone) through preventive medicine."]],
    drugs: ["ceftriaxone", "lactated-ringers", "norepinephrine", "levetiracetam", "midazolam"],
    warn: ["Bacterial meningitis can kill within hours; antibiotics come before any testing that would delay them.", "Military recruits receive meningococcal vaccine, but no vaccine covers every strain."],
    src: ["IDSA Practice Guidelines for the Management of Bacterial Meningitis", "CDC: Meningococcal Disease, Clinical Information and Prophylaxis", FM_SRC_FDA] },
  { id: "gastroenteritis", g: 7, dis: "gastroenteritis", name: "Infectious diarrhea", line: "The most common deployment illness",
    what: "Diarrhea and vomiting from bacteria (E. coli, Campylobacter, Shigella), viruses (norovirus) or parasites, spread through food, water and hands.",
    why: "Germs and their toxins make the gut secrete fluid and stop absorbing it. Fluid and salt losses cause dehydration, heat illness and kidney injury.",
    signs: ["Loose stools, cramps, nausea, vomiting", "Fever or bloody stools (more severe)", "Dizziness, low urine output, fast heart rate (dehydration)", "Several people sick at once"],
    care: [["asm", "Oral rehydration solution, the main treatment (WHO)."], ["cls", "Ondansetron for vomiting so oral fluids stay down; loperamide for watery diarrhea without fever or blood."], ["cpp", "IV fluid for severe dehydration; single-dose azithromycin as the preferred antibiotic for moderate to severe traveler's diarrhea in service members (TD expert guidelines, 2017)."], ["cpp", "Preventive medicine notified for outbreaks."]],
    drugs: ["ondansetron", "lactated-ringers", "moxifloxacin", "metronidazole"],
    warn: ["Loperamide is avoided with fever or bloody stools.", "Alcohol hand gel does not reliably kill norovirus; soap and water does.", "Dehydration adds to heat illness risk in hot climates."],
    src: ["Riddle MS et al. Guidelines for the prevention and treatment of travelers' diarrhea: a graded expert panel report. J Travel Med 2017", "WHO: Oral rehydration salts", FM_SRC_FDA] },
  { id: "tuberculosis", g: 7, dis: "tuberculosis", name: "Tuberculosis", line: "A slow infection that spreads through the air",
    what: "A lung infection caused by Mycobacterium tuberculosis, more common in many deployment regions and in detainee and refugee settings.",
    why: "The bacteria survive inside immune cells and grow slowly, forming lung cavities that spread bacteria with every cough.",
    signs: ["Cough for more than 2 to 3 weeks, sometimes with blood", "Fever, night sweats, weight loss", "Exposure in crowded settings"],
    care: [["cls", "Surgical mask on the patient; fit-tested N95 respirator for caregivers; separation from others."], ["cpp", "Reporting to preventive medicine and evacuation for testing; treatment uses several drugs for months under specialist care, which is not a field treatment."]],
    drugs: [],
    warn: ["Partial or interrupted treatment breeds drug-resistant TB.", "Contacts need screening through preventive medicine."],
    src: ["CDC: Tuberculosis, Clinical Overview and Infection Control", "ATS/CDC/IDSA Clinical Practice Guidelines: Treatment of Drug-Susceptible Tuberculosis, 2016"] },
  /* ---- metabolism and blood ---- */
  { id: "hyperkalemia", g: 8, dis: "hyperkalemia", name: "High potassium", line: "The rhythm killer of crush, burns and old blood",
    what: "A high potassium level, common in crush injury, burns, rhabdomyolysis, kidney failure, massive transfusion of stored blood and acidosis.",
    why: "Potassium sets the electrical resting state of heart cells. Too much makes the heart slow, then causes wide, bizarre beats, and then VF or asystole.",
    signs: ["Peaked T waves, wide QRS, sine-wave pattern on the monitor", "Weakness, slow heart rate", "High potassium on i-STAT", "Often no symptoms until arrest"],
    care: [["cpp", "Calcium (chloride or gluconate) to protect the heart, effective in minutes."], ["cpp", "Shifting potassium into cells: regular insulin with dextrose, and inhaled albuterol."], ["cpp", "Sodium bicarbonate for severe acidosis; fluids for crush and rhabdomyolysis; removal through the kidneys or dialysis after evacuation."]],
    drugs: ["calcium-chloride", "calcium-gluconate", "regular-insulin", "dextrose", "albuterol", "sodium-bicarbonate"],
    warn: ["Calcium protects the heart but does not lower potassium; the shift treatments do.", "Insulin can cause low blood sugar; glucose is checked repeatedly.", "Succinylcholine raises potassium and is avoided in crush, burns over a day old and paralysis."],
    src: ["JTS Clinical Practice Guideline: Hyperkalemia and Dialysis in the Deployed Setting, 2017", "American Heart Association: Cardiac arrest in special situations, hyperkalemia", FM_SRC_FDA] },
  { id: "hyponatremia", g: 8, dis: "hyponatremia", name: "Low sodium", line: "Too much water, not too little salt",
    what: "A low blood sodium level. In training and deployment it is mostly exercise-associated hyponatremia from drinking more water than is lost.",
    why: "Extra water dilutes the blood, and water moves into brain cells, which swell inside the skull. Severe cases cause seizures and brain herniation.",
    signs: ["Nausea, vomiting, headache after drinking large amounts of water", "Confusion, unusual behavior, seizures", "Swollen hands; normal or low body temperature", "Low sodium on i-STAT"],
    care: [["cls", "Stopping water intake; salty snacks for mild symptoms in an alert casualty."], ["cpp", "Hypertonic saline (3%) for confusion, seizures or other brain signs, per the exercise-associated hyponatremia consensus and WMS."], ["cpp", "Sodium rechecked after treatment; evacuation for severe cases."]],
    drugs: ["hypertonic-saline-3-percent", "midazolam", "ondansetron"],
    warn: ["Plain IV fluids (normal saline or lactated Ringer's) can worsen it.", "Heat illness and hyponatremia can look alike; a sodium level and a rectal temperature tell them apart.", "Correcting long-standing low sodium too fast can injure the brain; exercise-associated cases are acute."],
    src: ["Statement of the Third International Exercise-Associated Hyponatremia Consensus Development Conference, 2015", "Wilderness Medical Society Clinical Practice Guidelines for the Management of Exercise-Associated Hyponatremia, 2019 update", "Army TB MED 507, 2022"] },
  { id: "hypoglycemia", g: 8, dis: "hypoglycemia", name: "Low blood sugar", line: "The brain runs out of fuel",
    what: "A low blood glucose level, from diabetes treatment, insulin given for high potassium, heat stroke, severe malaria, alcohol, sepsis or starvation.",
    why: "The brain depends on glucose. As levels fall, adrenaline surges (shaking, sweating), then brain function fails (confusion, seizures, coma).",
    signs: ["Shaking, sweating, hunger, fast heart rate", "Confusion, odd behavior, slurred speech", "Seizures or unconsciousness", "Low glucose on a meter or i-STAT"],
    care: [["asm", "Oral glucose or sugary food for an alert casualty who can swallow."], ["cmc", "Glucose checked in every casualty with altered mental status."], ["cpp", "IV dextrose (FDA-labeled for insulin hypoglycemia) for a casualty who cannot swallow; glucagon IM or nasal (FDA-approved) when there is no IV."], ["cpp", "Repeat glucose checks and food once awake; the cause is looked for."]],
    drugs: ["dextrose"],
    warn: ["Low blood sugar is easy to mistake for TBI, intoxication or heat illness.", "It can return after treatment, especially with long-acting diabetes drugs."],
    src: ["American Diabetes Association Standards of Care in Diabetes: Hypoglycemia", FM_SRC_FDA] },
  { id: "diabetic-ketoacidosis", g: 8, dis: "diabetic-ketoacidosis", name: "Diabetic ketoacidosis", line: "No insulin, high sugar, high acid",
    what: "A life-threatening complication of diabetes when the body lacks insulin, often triggered by infection, missed insulin or dehydration.",
    why: "Without insulin, cells cannot use glucose, so the body burns fat into acidic ketones. High sugar pulls water out through the urine, causing severe dehydration and salt losses.",
    signs: ["Thirst, frequent urination, vomiting, abdominal pain", "Deep, fast breathing with a fruity breath smell", "Confusion and dehydration", "High glucose, low bicarbonate and ketones on testing"],
    care: [["cpp", "IV or IO fluid first, to replace the large water loss."], ["cpp", "Insulin infusion once potassium is known not to be low (ADA); potassium replacement as levels fall."], ["cpp", "Hourly glucose and frequent potassium on i-STAT; dextrose added as glucose falls; the trigger, such as infection, is treated; evacuation."]],
    drugs: ["lactated-ringers", "plasma-lyte", "regular-insulin", "potassium-chloride", "dextrose"],
    warn: ["Insulin started when potassium is low can cause a fatal arrhythmia.", "Bicarbonate is not routine in DKA."],
    src: ["American Diabetes Association Consensus Report: Hyperglycemic Crises in Adults with Diabetes, 2024", FM_SRC_FDA] },
  { id: "status-epilepticus", g: 8, dis: "status-epilepticus", name: "Status epilepticus", line: "A seizure that will not stop",
    what: "A seizure lasting more than 5 minutes, or repeated seizures without waking, from TBI, low sodium, low sugar, heat stroke, nerve agents, alcohol withdrawal or epilepsy.",
    why: "Continuous seizing exhausts the brain's energy supply, raises temperature and acid, and injures neurons. Over time the brain's GABA receptors move off the cell surface, so benzodiazepines work less the longer it lasts.",
    signs: ["Seizure lasting over 5 minutes", "Repeated seizures without regaining consciousness", "Low oxygen, high temperature during the seizure", "Subtle twitching in a casualty who does not wake (late)"],
    care: [["cls", "Protecting from injury, positioning on the side, oxygen; glucose checked."], ["cmc", "A benzodiazepine first: IM midazolam (FDA-approved for status epilepticus), IV lorazepam or diazepam (AES guideline)."], ["cpp", "Second-line drug if the seizure continues: levetiracetam, fosphenytoin or valproate (equally effective in the ESETT trial)."], ["cpp", "Airway and ventilation if seizures persist; the cause (low sodium, low glucose, TBI, heat) is treated."]],
    drugs: ["midazolam", "lorazepam", "diazepam", "levetiracetam", "propofol", "ketamine", "dextrose", "hypertonic-saline-3-percent"],
    warn: ["Delayed or too-small benzodiazepine dosing is the most common reason seizures continue.", "A paralyzed casualty can still be seizing; paralysis hides seizures."],
    src: ["American Epilepsy Society Guideline: Treatment of Convulsive Status Epilepticus, 2016", "ESETT trial, N Engl J Med 2019", FM_SRC_FDA] },
  /* ---- mind and stress ---- */
  { id: "ptsd", g: 9, dis: "ptsd", name: "Combat stress and PTSD", line: "Combat and operational stress reaction",
    what: "Combat and operational stress reaction (COSR) is the expected, often temporary response to extreme stress. Post-traumatic stress disorder (PTSD) is when symptoms last over a month and impair function.",
    why: "Threat triggers the brain's alarm system (amygdala) and stress hormones. In PTSD the alarm stays on and fear memories are not filed as past events, so reminders feel like present danger.",
    signs: ["COSR: exhaustion, shaking, numbness, confusion, inability to function after a traumatic event", "Nightmares, flashbacks, avoidance, being on edge", "Anger, sleep problems, drinking more", "Any talk of suicide or self-harm"],
    care: [["asm", "COSR care follows BICEPS: Brevity, Immediacy, Centrality, Expectancy, Proximity and Simplicity (rest, food, fluids, sleep and return to duty)."], ["cls", "Screening for suicide risk; removal of access to weapons when there is risk; behavioral health referral."], ["cpp", "PTSD treatment after evacuation: trauma-focused therapy first-line (VA/DoD), and sertraline or paroxetine (the two FDA-approved PTSD drugs)."]],
    drugs: [],
    warn: ["Benzodiazepines are not recommended for PTSD or for the period right after trauma (VA/DoD 2023).", "Suicide risk is checked directly; asking does not increase risk.", "Military Crisis Line: dial 988, then press 1."],
    src: ["VA/DoD Clinical Practice Guideline for the Management of PTSD and Acute Stress Disorder, 2023", "Army Techniques Publication ATP 6-22.5 and Field Manual FM 4-02.51: Combat and Operational Stress Control", "FDA prescribing information: sertraline, paroxetine"] }
);
