        vit: [["HR", "96"], ["BP", "118/72"], ["RR", "18"], ["SpO2", "97%"], ["Temp", "37.4 C"]],
        labs: [["Creatinine", "1.1 mg/dL", ""], ["Potassium", "4.6 mmol/L", ""]],
        q: "What fits best?",
        opts: [["Nothing by mouth until evacuation", 0, "He has no abdominal injury, and days without nutrition slow healing and immune function."],
          ["Oral fluids and calorie-dense rations, with intake and output tracked and fasciotomy wounds checked", 1, "Early oral nutrition supports healing, and tracking intake and output catches dehydration or kidney injury."],
          ["IV crystalloid alone for hydration", 0, "Crystalloid provides no meaningful calories or protein."],
          ["Food only after he is evacuated", 0, "Evacuation may be days away, and early feeding helps recovery."]],
