/* ---------- shared quiz ---------- */
function fmQuiz(key, Q) {
  S.fmqz = S.fmqz || {}; var Z = S.fmqz[key] || (S.fmqz[key] = { i: 0, a: -1, n: 0, ok: 0 }), q = Q[Z.i % Q.length];
  var c = '<div class="ispbar"><span>Question ' + (Z.i % Q.length + 1) + ' of ' + Q.length + '</span><span>' + Z.ok + ' of ' + Z.n + ' correct</span></div><section class="iscase ispcase"><p class="dvpq">' + esc(q[0]) + '</p><div class="ispopts">' + q[1].map(function (o, j) {
    var cls = Z.a < 0 ? "" : j === q[2] ? " right" : j === Z.a ? " wrong" : " dim";
    return '<button type="button" class="ispopt' + cls + '" data-fqa="' + key + '|' + j + '"' + (Z.a >= 0 ? ' disabled' : '') + '>' + esc(o) + '</button>';
  }).join("") + '</div>';
  if (Z.a >= 0) c += '<div class="ispteach"><b>' + (Z.a === q[2] ? "Correct" : "The answer: " + esc(q[1][q[2]])) + '</b><p>' + esc(q[3]) + '</p></div><div class="ispnav"><button class="btn small" data-fqn="' + key + '">Next question</button></div>';
  return c + '</section>';
}
var FMQ_SRC = function (k) { return { k9: typeof FM_K9_QUIZ !== "undefined" && FM_K9_QUIZ, anti: typeof FM_ANTI_QUIZ !== "undefined" && FM_ANTI_QUIZ, tele: typeof FM_TELE_QUIZ !== "undefined" && FM_TELE_QUIZ }[k]; };
function fmTopics(T) { return T.map(function (x) { return '<section class="dsec"><h3><span class="dic" aria-hidden="true">' + x[1] + '</span>' + esc(x[0]) + '</h3>' + String(x[2]).split("\n").filter(Boolean).map(function (p) { return '<p>' + esc(p) + '</p>'; }).join("") + '</section>'; }).join(""); }
function fmUl(a) { return a && a.length ? '<ul class="trl">' + a.map(function (s) { return '<li>' + esc(s) + '</li>'; }).join("") + '</ul>' : ''; }
/* ---------- K9 TCCC ---------- */
