  var hits = Object.keys(FM_ALLIED).filter(function (k) { var x = FM_ALLIED[k], t = (nameOf(k) + " " + k + " " + x.inn + " " + x.names.map(function (n) { return n[1]; }).join(" ")).toLowerCase(); return !q || t.indexOf(q) >= 0; }).sort(function (a, b) { return nameOf(a).localeCompare(nameOf(b)); });
  var fh = FM_FOREIGN.filter(function (r) { return !q || (r.join(" ")).toLowerCase().indexOf(q) >= 0; });
